window.DOSIK=window.DOSIK||{};DOSIK["pt_natsci"]={"1":[{"t":"table","title":"역학","head":["항목","내용"],"rows":[["등가속도 운동","v = v₀ + at, s = v₀t + ½at², v² - v₀² = 2as로 푼다 · 처음 속력 v₀에서 등가속도로 멈출 때 평균 속력은 v₀/2이므로 이동 거리는 s = v₀t/2 · 같은 v₀에서 출발해 멈추면 이동 거리는 정지까지 걸린 시간에 비례"],["역학적 에너지 보존","마찰과 공기저항이 없으면 위치에너지 mgh와 운동에너지 ½mv²의 합이 보존 · 높이 h만큼 내려온 물체의 속력은 v = √(2gh)이고 질량과 경사각에 관계없음 · h에서 정지 출발해 h/2 지점을 지나면 내려온 높이가 h/2이므로 v = √(gh)"],["뉴턴 법칙과 운동량","알짜힘 F = ma이고 운동량 p = mv, 충격량 FΔt = Δp · 외력이 없으면 충돌 전후 운동량의 합이 보존 · 탄성 충돌에서는 운동에너지도 보존"],["일과 운동에너지","일 W = Fs cosθ이고 알짜힘이 한 일은 운동에너지 변화량과 같음 · 일률 P = W/t = Fv"],["원운동과 만유인력","등속 원운동의 구심가속도는 v²/r이고 구심력은 mv²/r · 만유인력은 F = GMm/r²이고 지표 근처 중력가속도는 g = GM/R²"],["회전 운동 에너지","회전 운동에너지는 ½Iω²이고 미끄러짐 없이 구르면 v = ωR · 관성모멘트는 얇은 고리 MR², 원판·속찬 원기둥 ½MR², 속찬 구 ⅖MR² · 굴러가는 얇은 고리는 병진·회전 에너지가 같아 전체 운동에너지가 Mv²"],["단진동","용수철 진자의 주기는 T = 2π√(m/k)이고, 진폭이 작은 단진자의 주기는 T = 2π√(L/g)로 질량과 무관 · 용수철의 탄성 위치에너지는 ½kx²"]]}],"2":[{"t":"table","title":"열역학","head":["항목","내용"],"rows":[["이상기체 상태방정식","이상기체는 PV = nRT를 따르며 T는 절대온도(K) · 단원자 이상기체의 내부에너지는 U = (3/2)nRT로 온도에만 의존"],["열역학 제1법칙","기체가 흡수한 열 Q = 내부에너지 변화 ΔU + 기체가 한 일 W · 기체가 한 일은 P-V 그래프 아래 넓이이며 등압과정에서는 W = PΔV"]]},{"t":"table","title":"열역학 과정","head":["과정","식","결과"],"rows":[["등적과정","W = 0","Q = ΔU"],["등온과정","ΔU = 0","Q = W"],["단열과정","Q = 0","W = -ΔU이므로 단열팽창하면 온도가 내려감"]]},{"t":"table","title":"열기관과 엔트로피","head":["항목","내용"],"rows":[["열기관 효율","e = W/Q_H = 1 - Q_C/Q_H · 한 사이클에 4000 J을 받아 1000 J의 일을 하면 효율은 0.25이고 3000 J을 저온부로 버림"],["카르노 기관과 제2법칙","두 열원 사이에서 작동하는 가역 카르노 기관의 효율은 e = 1 - T_C/T_H(절대온도) · 600 K와 300 K 사이면 0.5 · 같은 두 열원 사이의 어떤 기관도 카르노 기관보다 효율이 높을 수 없고, 효율 1인 기관은 없음"],["열량과 엔트로피","온도 변화에 필요한 열량은 Q = mcΔT(c는 비열) · 가역과정의 엔트로피 변화는 ΔS = Q/T이고, 고립계의 엔트로피는 줄어들지 않음"]]}],"3":[{"t":"table","title":"전자기학","head":["항목","내용"],"rows":[["쿨롱 법칙과 전기장","두 점전하 사이의 힘은 F = kq₁q₂/r²이고 전기장은 E = F/q, 점전하의 전기장은 E = kq/r² · 균일한 전기장에서 전위차는 V = Ed"],["회로","옴의 법칙은 V = IR이고 전력은 P = VI = I²R = V²/R · 직렬연결 합성저항은 R₁ + R₂, 병렬연결은 1/R = 1/R₁ + 1/R₂"],["축전기","전기용량 C = Q/V이고 평행판 축전기는 C = ε₀A/d · 저장 에너지는 ½CV²"],["전류가 만드는 자기장","긴 직선 도선에서 거리 r인 곳의 자기장은 B = μ₀I/(2πr)이고, 단위 길이당 감은 수 n인 솔레노이드 내부는 B = μ₀nI · 방향은 오른손 법칙으로 정함"]]},{"t":"tree","title":"자기장 속 전하의 원운동","root":"균일한 자기장 B에 수직으로 들어온 전하","branches":[["구심력","로런츠 힘 F = qvB를 구심력으로 받아 원운동"],["반지름과 주기","반지름 r = mv/(qB), 주기 T = 2πm/(qB)로 주기는 속력과 무관"],["가속도","가속도 크기는 qvB/m"],["운동에너지","자기력은 속도에 수직이라 일을 하지 않아 운동에너지 ½mv²가 일정"]]},{"t":"vs","title":"전자기 유도와 변위전류","cols":[{"name":"전자기 유도","items":["유도기전력은 ε = -dΦ/dt(패러데이 법칙)","유도전류는 자속 변화를 방해하는 방향으로 흐름(렌츠 법칙)"]},{"name":"변위전류와 앙페르-맥스웰 법칙","items":["변하는 전기장 선속은 변위전류 I_d = ε₀dΦ_E/dt를 만들어 자기장을 유도","반지름 R인 원형 평행판 축전기를 전류 i로 충전할 때, 판 사이 중심축에서 r(< R)인 곳의 자기장은 B = μ₀ir/(2πR²)로 r에 비례","판 바깥(r > R)에서는 B = μ₀i/(2πr)"]}]}],"4":[{"t":"table","title":"파동과 광학","head":["항목","내용"],"rows":[["사인파 식 읽기","y = A sin(kx - ωt)에서 진폭은 A, 파장 λ = 2π/k, 주기 T = 2π/ω · 파동 속력은 v = ω/k = fλ · k가 3배이면 파장은 1/3배이고, ω가 2배·k가 3배이면 속력은 2/3배"],["줄의 파동 속력","줄을 따라 가는 파동의 속력은 v = √(F/μ)(F 장력, μ 선밀도) · 차원 분석으로 v = CFˣμʸ에서 x = ½, y = -½을 얻으며 장력을 2배로 하면 속력은 √2배"],["정상파","양 끝이 고정된 길이 L인 줄의 정상파는 λ = 2L/n(n = 1, 2, 3, …) · 진동수는 f = nv/(2L)"],["굴절과 전반사","굴절률 n = c/v이고 스넬 법칙은 n₁sinθ₁ = n₂sinθ₂ · 굴절률이 큰 매질에서 작은 매질로 갈 때 입사각이 임계각(sinθc = n₂/n₁)보다 크면 전반사가 일어남"],["간섭과 회절","영의 이중슬릿에서 밝은 무늬 간격은 Δx = Lλ/d(L 스크린 거리, d 슬릿 간격)"],["종파·횡파와 도플러 효과","소리는 종파이고 빛은 횡파라서 빛만 편광됨 · 음원과 관측자가 가까워지면 관측 진동수가 커지고 멀어지면 작아짐"]]},{"t":"vs","title":"간섭의 조건","cols":[{"name":"보강간섭","items":["경로차가 파장의 정수배"]},{"name":"상쇄간섭","items":["경로차가 반파장의 홀수배"]}]}],"5":[{"t":"table","title":"현대물리","head":["항목","내용"],"rows":[["핵반응 보존","핵반응에서 질량수의 합과 원자번호(전하)의 합은 보존 · ²H + ³H → ⁴He + n + 17.6 MeV(D-T 핵융합)에서 2 + 3 = 4 + 1 · 방출 에너지는 질량결손 Δm에 대해 E = Δmc²"],["특수상대성이론","모든 관성계에서 물리법칙과 진공 중 빛의 속력 c는 같고, 어떤 물체도 c보다 빠를 수 없음 · γ = 1/√(1 - v²/c²)일 때 고유시간 Δt₀는 상대 운동하는 관측자에게 γΔt₀로 길어지고, 고유길이 L₀는 운동 방향으로 L₀/γ로 짧아짐 · v = 0.6c이면 γ = 1.25"],["광자 에너지","광자 에너지는 E = hf = hc/λ이고 hc ≈ 1240 eV·nm이므로 E(eV) ≈ 1240/λ(nm) · 파장 500 nm 광자는 약 2.48 eV"],["드브로이 물질파","물질파 파장은 λ = h/p이고 전자의 운동에너지는 K = p²/(2m) = h²/(2mλ²) · 같은 파장이면 광자 에너지 hc/λ가 전자 운동에너지보다 훨씬 큼"],["1차원 무한 퍼텐셜 우물","폭 L인 무한 퍼텐셜 우물에 갇힌 입자의 에너지는 Eₙ = n²h²/(8mL²)로 n²에 비례 · 전자는 L = 1 nm일 때 E₁ ≈ 0.376 eV · n = 3에서 n = 1로 전이할 때 방출 광자 에너지는 E₃ - E₁ = 8E₁"],["반감기와 광전효과","남은 양은 N = N₀(½)^(t/T)(T 반감기) · 광전효과에서 튀어나온 전자의 최대 운동에너지는 K_max = hf - W(W 일함수)이고, 빛의 세기가 아니라 진동수가 문턱값을 넘어야 전자가 나옴"]]},{"t":"table","title":"방사성 붕괴","head":["붕괴","질량수","원자번호","중성자 수"],"rows":[["α 붕괴","4 줄어듦","2 줄어듦","—"],["β⁻ 붕괴","그대로","1 늘음","1 줄음"],["β⁺ 붕괴","—","1 줄음","1 늚"]]}],"6":[{"t":"table","title":"물질의 구조와 화학결합","head":["항목","내용"],"rows":[["분자 궤도함수 에너지 순서","2주기 동핵 이원자 분자 중 B₂, C₂, N₂는 π₂p가 σ₂p보다 낮고, O₂, F₂는 σ₂p가 π₂p보다 낮음 · 결합 차수 = (결합성 전자 수 - 반결합성 전자 수)/2 · N₂의 HOMO는 σ₂p, O₂와 F₂의 HOMO는 π*₂p"],["결합 차수와 자기성","결합 차수는 Li₂ 1, B₂ 1, C₂ 2, N₂ 3, O₂ 2, F₂ 1이고 결합 에너지는 N₂가 가장 큼 · B₂(π₂p에 홀전자 2)와 O₂(π*₂p에 홀전자 2)는 상자기성, C₂, N₂, F₂는 반자기성 · B₂의 LUMO는 결합성 σ₂p"],["등전자 화학종","가전자가 10개인 N₂, CO, CN⁻, NO⁺는 결합 차수 3이고 반자기성 · NO는 가전자 11개로 홀전자 1개를 가짐 · 이온의 결합 차수는 전자를 더하거나 빼서 같은 방식으로 셈"],["할로젠","할로젠 단체의 반응성은 F₂ > Cl₂ > Br₂ > I₂이고, Br₂는 25℃에서 적갈색 액체 · 할로젠화 수소의 끓는점은 수소 결합 때문에 HF가 가장 높고 HCl이 가장 낮음 · 산소산 HXO의 산 세기는 중심 원자의 전기음성도가 클수록 커서 HClO > HBrO > HIO"],["착화합물 이성질체","배위수 6인 착화합물은 팔면체 구조 · MA₄B₂형과 MA₃B₃형은 기하이성질체가 각각 2개(cis·trans, fac·mer) · [M(AA)₂B₂]형의 cis 이성질체는 거울상과 겹치지 않아 광학 활성"],["결정장 이론","정사면체 결정장에서 d 오비탈은 e(dz², dx²-y²)가 아래, t₂(dxy, dxz, dyz)가 위로 갈라짐 · 결정장 안정화 에너지는 e 전자 하나당 -0.6Δt, t₂ 전자 하나당 +0.4Δt · Mn²⁺(d⁵) 고스핀은 e²t₂³이라 안정화 에너지가 0이고 홀전자가 5개"]]},{"t":"table","title":"혼성과 분자 모양","head":["전자쌍 수","혼성","모양"],"rows":[["2개","sp","직선, 180°"],["3개","sp²","평면 삼각형, 120°"],["4개","sp³","사면체, 109.5°"]]},{"t":"def","term":"혼성의 예","text":"BF₃는 평면 삼각형, CH₄와 C₂H₆의 탄소는 sp³"}],"7":[{"t":"table","title":"유기화학","head":["항목","내용"],"rows":[["탄소의 혼성","단일결합만 가진 탄소는 sp³, 이중결합 탄소는 sp², 삼중결합 탄소는 sp · 삼중결합은 σ 결합 1개와 π 결합 2개로 이루어짐 · 알렌(H₂C=C=CH₂)의 가운데 탄소는 sp이고 양 끝 CH₂ 평면이 서로 수직이라 모든 원자가 한 평면에 있지 않음"],["아세틸렌의 반응과 폴리아세틸렌","아세틸렌에 산 촉매로 물을 첨가하면 엔올(비닐알코올)을 거쳐 호변이성질화로 아세트알데하이드 CH₃CHO가 됨 · C=O 신축 진동은 IR 스펙트럼 1700~1750 cm⁻¹ 부근에서 강하게 나타남 · π 결합이 사슬 전체로 이어진 trans-폴리아세틸렌은 도핑하면 전도성 고분자가 됨"],["불포화도","불포화도 = (2C + 2 + N - H - X)/2이며 고리 하나나 이중결합 하나가 1 · C₄H₈O와 C₆H₁₂O는 불포화도가 1이므로 고리 하나 또는 C=C·C=O 하나를 가짐"],["구조 이성질체 세기","C₆H₁₂O의 케톤은 2-헥산온, 3-헥산온, 3-메틸-2-펜탄온, 4-메틸-2-펜탄온, 2-메틸-3-펜탄온, 3,3-다이메틸-2-뷰탄온의 6개 · C₄H₈O 중 알코올을 뺀 고리형은 산소가 고리에 든 6개(테트라하이드로퓨란, 옥세테인 2개, 옥시레인 3개)와 메톡시사이클로프로페인을 합해 7개"],["벤젠의 친전자성 치환","벤젠은 첨가가 아니라 고리의 H를 바꾸는 친전자성 방향족 치환 반응을 함 · Cl₂/FeCl₃은 클로로벤젠, HNO₃/H₂SO₄는 나이트로벤젠, CH₃Cl/AlCl₃(프리델-크래프츠 알킬화)는 톨루엔을 만듦 · 나이트로벤젠(약 211℃)은 톨루엔(약 111℃)보다 끓는점이 높음"],["수소 질량 백분율","수소 질량 백분율 = 수소 질량÷분자량×100 · 에틸렌 C₂H₄는 4/28 ≈ 14.3%, 아세틸렌 C₂H₂는 2/26 ≈ 7.7%, 알렌 C₃H₄는 4/40 = 10%"]]}],"8":[{"t":"table","title":"화학반응·평형·산염기","head":["항목","내용"],"rows":[["평형 상수","평형 상수 식에는 기체와 수용액 화학종만 넣고 고체와 순수한 액체는 넣지 않음 · A(s) ⇄ B(g) + C(g)의 Kp = P_B·P_C · 처음부터 B가 있으면 생성된 양 x를 더해 P_B = P_B,0 + x, P_C = x로 놓고 전체 압력 조건으로 x를 구함"],["산화·환원 균형","산화수 변화로 주고받는 전자 수를 맞춘 뒤 산성 용액에서는 H⁺와 H₂O로, 염기성 용액에서는 H⁺를 같은 수의 OH⁻로 바꿔 H₂O로 정리 · MnO₄⁻는 산성에서 Mn²⁺(전자 5개 받음), 염기성·중성에서 MnO₂(전자 3개 받음) · 산성에서 2MnO₄⁻ + 5SO₃²⁻ + 6H⁺ → 2Mn²⁺ + 5SO₄²⁻ + 3H₂O"],["완충 용액과 해리 백분율","pH = pKa + log([A⁻]/[HA])(헨더슨-하셀바흐) · 50% 해리이면 pH = pKa, 약 91% 해리이면 [A⁻]/[HA] ≈ 10이라 pH = pKa + 1"],["매우 묽은 강산","25℃에서 Kw = [H⁺][OH⁻] = 1.0×10⁻¹⁴이고 pH + pOH = 14 · 1.0×10⁻⁸ M 염산은 물의 자동이온화를 무시할 수 없어 전하 균형 [H⁺] = [Cl⁻] + [OH⁻]로 풀며, [H⁺] ≈ 1.05×10⁻⁷ M, pH ≈ 6.98 · 농도 순서는 [Cl⁻] < [OH⁻] < [H⁺]"],["농도 환산","몰농도(M) = 10×밀도(g/mL)×질량 백분율(%)÷몰질량 · 용액을 냉각해 부피가 줄면 몰농도는 커지지만 질량 백분율은 그대로"],["전지와 네른스트 식","25℃에서 E = E° - (0.0592/n)log Q이고 ΔG° = -nFE° · 환원되는 물질이 산화제이며, 수소 전극에서 H⁺는 전자를 받아 H₂가 되므로 산화제 · H⁺ 농도가 줄면(pH 증가) 수소 전극 쪽 환원 전위가 낮아져 전지 전위가 작아짐"],["용해와 착이온","난용성 염 AB(s) ⇄ A⁺ + B⁻(Ksp)와 착이온 형성 A⁺ + 3CN⁻ ⇄ A(CN)₃²⁻(Kf)을 더한 전체 반응의 평형 상수는 K = Ksp·Kf · 착이온이 생기면 A⁺가 소모되어 난용성 염의 용해도가 커짐 · 같은 이온을 넣으면 용해도가 줄어듦(공통 이온 효과)"]]}],"9":[{"t":"table","title":"반응 차수별 식","head":["차수","식","반감기"],"rows":[["0차 반응","[A] = [A]₀ - kt로 농도가 시간에 따라 일정하게 줄어듦","t½ = [A]₀/(2k)는 처음 농도에 비례"],["1차 반응","ln[A] = ln[A]₀ - kt · 방사성 붕괴가 대표적 · ln[A]를 시간에 대해 그리면 기울기 -k인 직선","t½ = 0.693/k는 처음 농도와 관계없음"],["2차 반응","1/[A] = 1/[A]₀ + kt","t½ = 1/(k[A]₀)는 처음 농도에 반비례"]]},{"t":"table","title":"반응속도론","head":["항목","내용"],"rows":[["속도 법칙","반응 속도는 v = k[A]ᵐ[B]ⁿ으로 나타내고 반응 차수 m, n은 화학반응식 계수가 아니라 실험으로 정함 · 전체 차수는 m + n이고 속도 상수 k는 온도에 따라 달라짐"],["아레니우스 식","속도 상수는 k = Ae^(-Ea/RT) · 온도가 높을수록, 활성화 에너지 Ea가 작을수록 k가 커짐 · ln k를 1/T에 대해 그리면 기울기 -Ea/R인 직선"],["촉매","촉매는 활성화 에너지가 낮은 다른 경로를 제공해 정반응과 역반응을 모두 빠르게 함 · 반응 엔탈피 ΔH와 평형 상수, 평형 조성은 바꾸지 않고 평형에 빨리 도달하게 함"],["반응 메커니즘","여러 단계로 이루어진 반응에서 가장 느린 단계가 속도 결정 단계이고 전체 속도 법칙은 이 단계로 정해짐 · 단일 단계(기본 반응)의 차수는 그 단계의 분자 수와 같음 · 반응이 일어나려면 활성화 에너지 이상의 에너지와 알맞은 방향을 가진 유효 충돌이 필요"]]}],"10":[{"t":"table","title":"세포와 물질대사","head":["항목","내용"],"rows":[["원핵세포와 진핵세포","대장균 같은 원핵세포에는 핵막으로 싸인 핵과 미토콘드리아가 없음 · 진핵세포의 핵막은 이중막 · 세포벽 성분은 세균 펩티도글리칸, 균류(효모·곰팡이) 키틴·글루칸, 식물 셀룰로오스"],["세포소기관","세포골격 굵기는 미세소관(약 25 nm) > 중간섬유(8~12 nm) > 미세섬유(약 7 nm) · 리소좀 효소는 산성(pH 약 5)에서 작용하고, 골지체는 시스 면으로 소포체 소낭을 받아 트랜스 면으로 내보냄 · 활면소포체는 Ca²⁺를 저장하고, 글리옥시좀은 지방을 저장하는 식물 종자에 있음"],["탄수화물","탄수화물의 단량체는 단당류 · 아밀로오스는 포도당이 α-1,4 글리코시드 결합으로 이어지고, 아밀로펙틴과 글리코겐은 가지 부분에 α-1,6 결합이 있음 · 곤충 외골격·갑각류 껍질·곰팡이 세포벽의 키틴은 N-아세틸글루코사민 다당류이고, 콜라겐은 단백질"],["단백질 구조","아미노산이 펩티드 결합으로 이어진 서열이 1차 구조이고, 펩티드 결합은 물이 빠지는 탈수 축합으로 생김 · 2차 구조에서 α 구조는 나선, β 구조는 병풍 모양 · 열은 3차 구조를 풀어 변성시키며, 4차 구조 없이 폴리펩티드 하나로 기능하는 단백질도 많음"]]},{"t":"table","title":"효소 저해제","head":["저해제","Vmax","Km"],"rows":[["경쟁적 저해제","바꾸지 않음 · 활성부위를 두고 기질과 경쟁","높임"],["비경쟁적 저해제","낮춤","그대로"],["무경쟁적 저해제","낮춤 · 효소-기질 복합체에만 붙음","낮춤"]]},{"t":"flow","title":"세포호흡","steps":["해당과정은 세포질에서 산소 없이 일어나 포도당 1분자를 피루브산 2분자로 나누며 ATP 2개를 쓰고 4개를 만들어 순 2개를 얻음","TCA 회로는 미토콘드리아 기질에서 일어남","산화적 인산화는 미토콘드리아 내막의 전자전달계에서 일어남","세포호흡의 전자운반체는 NAD⁺와 FAD"]},{"t":"table","title":"광합성","head":["항목","내용"],"rows":[["명반응","명반응은 틸라코이드에서 일어나며 H₂O가 광분해되어 O₂가 나오므로 방출되는 O₂는 CO₂가 아니라 물에서 옴 · 광계 II에서 들뜬 전자의 에너지로 H⁺ 농도 기울기가 생겨 ATP가 합성되고, 최종 전자수용체 NADP⁺가 NADPH가 됨 · 광인산화와 산화적 인산화는 모두 화학삼투로 ATP를 만듦"],["캘빈 회로","캘빈 회로는 스트로마에서 루비스코가 CO₂를 RuBP에 고정하며 직접 만드는 탄수화물은 G3P(PGAL)"],["C₃ 식물","엽육세포에서 CO₂를 고정"],["C₄ 식물","PEP 카르복실화효소로 CO₂를 모아 유관속초세포의 캘빈 회로로 보내 광호흡 손실이 적음"],["CAM 식물","밤에 기공을 열어 CO₂를 유기산으로 고정"]]}],"11":[{"t":"table","title":"동물생리와 항상성","head":["항목","내용"],"rows":[["혈관","혈압은 동맥에서 가장 높고 모세혈관, 정맥으로 갈수록 낮아짐 · 총단면적은 모세혈관이 가장 크고, 그래서 혈류 속도는 모세혈관에서 가장 느림"]]},{"t":"table","title":"세포 신호전달 거리","head":["신호","작용"],"rows":[["내분비 신호","호르몬이 혈액을 따라 먼 표적세포에 감"],["국소분비 신호","주변의 다른 세포에 작용"],["자가분비 신호","분비한 세포 자신에 작용"],["신경전달물질","신경세포 말단에서 시냅스 틈으로 확산"]]},{"t":"vs","title":"호르몬 수용체","cols":[{"name":"수용성 호르몬","items":["펩타이드 호르몬과 에피네프린 같은 수용성 호르몬은 세포막을 통과하지 못함","세포 표면 수용체(G 단백질 연결 수용체 등)에 결합"]},{"name":"지용성 호르몬","items":["스테로이드 호르몬 같은 지용성 호르몬은 세포막을 통과","세포 안 수용체와 결합"]}]},{"t":"table","title":"면역","head":["항목","내용"],"rows":[["적응면역","MHC I은 거의 모든 유핵세포에, MHC II는 항원제시세포에 있으며 항원제시세포는 둘 다 가짐 · 세포독성 T세포는 MHC I로 제시된 항원을 인식해 감염된 세포를 죽임 · B세포 수용체와 항체는 항원 표면의 항원결정부(에피토프)를 인식"],["림프구 성숙과 선택","T세포는 골수에서 만들어져 흉선에서 성숙하고, B세포는 골수에서 성숙 · 골수에서 자기 항원에 강하게 반응하는 미성숙 B세포는 세포자멸사로 제거됨 · 동형전환은 성숙 B세포가 항체 종류를 바꾸는 과정"],["난할","난황이 몰린 쪽이 식물극, 반대쪽이 동물극 · 난할 중 세포주기는 G₁, G₂가 거의 없이 S기와 M기만 반복되어 세포가 작아짐 · 개구리 알은 난황이 많아도 알 전체가 갈라지는 전할(불균등 전할)이고, 조류 알은 부분할을 함"]]}],"12":[{"t":"table","title":"유전과 분자생물학","head":["항목","내용"],"rows":[["체세포분열과 감수분열","DNA 복제는 분열 전 간기 S기에 한 번만 일어남 · 감수분열은 2회 분열로 딸세포 4개를 만들며, 감수분열 I 전기에 상동염색체가 접합해 교차가 일어나고 감수분열 II에서 자매염색분체가 분리됨 · 감수분열 딸세포는 교차와 독립 분배로 유전적으로 서로 다름"],["연관 유전 확률","같은 염색체에 있는 유전자는 교차가 없으면 함께 전달됨 · 상반 연관(Ad/aD) 개체를 자가교배하면 자손은 Ad/Ad 1/4, Ad/aD 1/2, aD/aD 1/4 · 다른 염색체의 유전자는 독립이므로 확률을 곱함"],["DNA 복제","DNA 복제는 반보존적 · 프리메이스가 RNA 프라이머를 만들고 DNA 중합효소가 5'→3' 방향으로 합성 · 선도가닥은 연속 합성되고, 지연가닥은 불연속으로 합성되어 오카자키 절편이 생김"],["전사와 번역","RNA 중합효소가 결합해 전사를 시작하는 DNA 서열이 프로모터이고, 진핵세포는 RNA 중합효소 I, II, III이 RNA를 나누어 합성 · 원핵생물은 오페론으로 한 프로모터에서 여러 유전자를 하나의 mRNA로 전사 · 진핵세포에서 전사와 mRNA 가공(5' 캡, 폴리 A 꼬리, 스플라이싱)은 핵에서, 번역은 세포질의 리보솜에서 tRNA를 이용해 일어남"],["유전암호와 돌연변이","엑손과 인트론이 모두 전사되고 인트론은 스플라이싱으로 제거됨 · 유전암호는 중복되어 있어 코돈이 바뀌어도 아미노산이 그대로인 침묵 돌연변이가 있음 · 염기 중 아데닌·구아닌은 퓨린, 시토신·티민·우라실은 피리미딘이며 뉴클레오티드는 포스포디에스터 결합으로 이어짐"]]},{"t":"vs","title":"오페론 조절","cols":[{"name":"젖당 오페론","items":["억제자에 의한 음성 조절(유도자 알로락토스가 붙은 억제자는 작동자에서 떨어짐)","cAMP-CAP 복합체에 의한 양성 조절"]},{"name":"트립토판 오페론","items":["공동억제자인 트립토판이 결합한 억제자가 작동자에 붙어 전사를 막는 음성 조절","감쇠 조절 · 감쇠는 전사와 번역이 동시에 일어나는 원핵생물에서만 가능"]}]},{"t":"table","title":"염색질·유전자 전달·생명공학","head":["항목","내용"],"rows":[["염색질과 후성유전","양전하를 띤 히스톤과 음전하를 띤 DNA가 결합해 지름 약 11 nm의 뉴클레오솜을 만들고, 그 위 단계가 30 nm 섬유 · 히스톤 N-말단 꼬리의 아세틸화는 염색질을 느슨하게 해 전사를 촉진하고, DNA 메틸화는 전사를 억제 · 이런 염색질 변형은 되돌릴 수 있음"],["형질전환","세포 밖 DNA를 직접 받아들이는 것"],["형질도입","박테리오파지가 세균 DNA 조각을 옮기는 것"],["접합","선모로 세포가 연결되어 플라스미드 등을 옮기는 것"],["수평적 유전자 전이","이들은 개체 사이의 수평적 유전자 전이이며 항생제는 내성균을 선택해 그 비율을 늘림"],["RT-PCR","역전사효소로 RNA에서 cDNA를 만들고 유전자 특이적 프라이머, 열안정성 DNA 중합효소, dNTP로 증폭"],["겔 전기영동","DNA는 음전하라 겔 전기영동에서 양극으로 이동"],["블롯과 분석","서던 블롯은 DNA, 노던 블롯은 RNA, 웨스턴 블롯·ELISA·에드만 분해·등전점 전기영동은 단백질을 분석"],["CRISPR-Cas9","가이드 RNA가 표적을 안내해야 Cas9이 DNA를 자름"]]}],"13":[{"t":"table","title":"진화·생태·분류","head":["항목","내용"],"rows":[["세 영역","세균은 RNA 중합효소가 한 종류이고 히스톤이 없으며 세포벽에 펩티도글리칸이 있음 · 고세균과 진핵생물은 히스톤과 결합한 DNA를 가지고 RNA 중합효소가 여러 종류 · 막으로 싸인 세포소기관과 섬모는 진핵세포의 특징"],["하디-바인베르크 평형","평형 조건은 돌연변이 없음, 무작위 교배, 유전자 흐름(이입·이출) 없음, 매우 큰 집단, 자연선택 없음 · 평형 집단에서 대립유전자 빈도 p, q에 대해 유전자형 빈도는 p² + 2pq + q² = 1"],["진화 요인","유전자 부동은 우연에 의해 대립유전자 빈도가 세대마다 무작위로 변하는 현상이며 작은 집단에서 큼 · 창시자 효과와 병목 효과는 유전자 부동의 예 · 유전자 흐름은 개체나 배우자의 이동으로 빈도를 바꾸고, 균형선택에는 빈도 의존적 선택과 이형접합자 우위(잡종강세)가 있음"],["속씨식물","속씨식물은 꽃을 가진 종자식물로 식물계에서 가장 다양하고 널리 분포 · 중복수정은 속씨식물에만 있으며 외떡잎식물과 쌍떡잎식물이 모두 속씨식물"],["열대우림","열대우림은 연중 고온다습해 기온 변화가 작고, 단위 면적당 식물 종 다양성이 육상생태계 중 가장 높음 · 유기물이 빨리 분해되고 양분이 씻겨 나가 토양은 산성이고 척박 · 일교차가 큰 군계는 사막"]]},{"t":"tree","title":"동물 분류","root":"좌우대칭동물(삼배엽성)","branches":[["선구동물","원구가 입이 됨"],["후구동물","원구가 항문이 되며 입은 반대쪽에 새로 생김"],["촉수담륜동물","선구동물 중 연체·환형·편형동물이 속함 · 환형동물은 진체강동물"],["탈피동물","선구동물 중 절지·선형동물이 속함"]]}],"14":[{"t":"table","title":"대기권의 구조","head":["층","특징"],"rows":[["대류권","위로 갈수록 기온이 내려가고 기상 현상이 나타나며 두께는 적도(약 16~18 km)가 극(약 8~10 km)보다 두꺼움"],["성층권","오존의 자외선 흡수로 위로 갈수록 기온이 올라 상부 경계(약 50 km)에서 가장 높음"],["중간권","위로 갈수록 기온이 내려가 대류가 일어나지만 수증기가 거의 없어 기상 현상은 없음"],["열권","전리층이 있고 오로라가 나타남"]]},{"t":"vs","title":"전선","cols":[{"name":"온난 전선면","items":["기울기가 완만해 층운형 구름(난층운)이 넓게 생기고 지속적인 비가 내림"]},{"name":"한랭 전선면","items":["기울기가 급해 적운형 구름(적란운)과 소나기가 생김"]}]},{"t":"def","term":"온대 저기압","text":"성질이 다른 찬 기단과 따뜻한 기단이 만나는 곳에서 생김"},{"t":"table","title":"해양과 기후","head":["항목","내용"],"rows":[["표층 순환","표층 해류는 바람과 해수면의 마찰로 생김 · 아열대 환류는 북반구에서 시계 방향, 남반구에서 반시계 방향으로 돎 · 멕시코 만류, 쿠로시오 해류, 캘리포니아 해류, 카나리아 해류는 북반구 아열대 환류이고, 페루(훔볼트) 해류는 남태평양 환류에 속함"],["심층 순환","수온과 염분에 따른 밀도 차로 일어나는 심층 순환을 열염순환이라 함 · 고위도에서 차갑고 짠 표층수가 가라앉아 심층수가 되며, 심해의 해수를 섞음"],["해일","지진해일은 파장이 수심보다 훨씬 길어 깊은 바다에서도 천해파(장파)로 행동하며 속력은 v = √(gh)로 수심에만 관계됨 · 해안에 가까워져 수심이 얕아지면 속력이 줄고 파고가 높아짐 · 폭풍해일에서 기압이 1 hPa 낮아지면 해수면이 약 1 cm 올라감"],["날씨와 기후","날씨는 특정 시간·장소의 대기 상태이고 기후는 장기간의 평균 상태이며 기온·강수량·바람·기압이 기후요소 · 태양 활동과 지구 공전궤도 변화는 기후변화의 외적 요인, 대기·해양 상호작용과 화산 활동, 지표 변화는 내적 요인 · 빙하 코어와 심해저 퇴적물, 나무 나이테로 과거 기후를 추정"]]}],"15":[{"t":"table","title":"지질과 판구조론","head":["항목","내용"],"rows":[["광물 분류","감람석, 휘석, 각섬석, 흑운모, 장석, 석영은 규산염 광물 · 방해석(CaCO₃)과 돌로마이트(CaMg(CO₃)₂)는 탄산염, 암염(NaCl)은 할로젠화, 황동석(CuFeS₂)은 황화, 금강석은 원소 광물"],["보웬의 반응 계열","불연속 계열은 감람석 → 휘석 → 각섬석 → 흑운모 순으로, 연속 계열은 Ca 사장석에서 Na 사장석으로 정출 · 고온에서 먼저 정출되는 광물일수록 Mg·Fe·Ca가 많고 어두우며, 저온의 정장석·백운모·석영은 밝음 · 용융은 정출의 역순으로 일어나며 사장석은 Ca-Na 고용체"],["지진과 지진파","탄성에너지가 처음 방출된 지점이 진원이고 그 바로 위 지표가 진앙 · P파는 진행 방향과 진동 방향이 나란한 종파로 고체·액체를 모두 통과하고 S파보다 빠르며, S파는 횡파로 고체만 통과 · P파와 S파는 실체파이고, 두 파의 도착 시간 차(PS시)는 진앙 거리가 멀수록 커짐"],["지구 내부","외핵은 액체라 S파가 통과하지 못하므로 S파 암영대는 진앙각 103° 이상 전체이고, P파 암영대(103°~142°)는 그보다 좁음 · 내핵은 압력이 커서 고체이고, 상부 맨틀은 감람암질이며 지진파 속도가 줄어드는 저속도층이 있음 · 해양지각(현무암질, SiO₂ 약 50%)은 대륙지각(화강암질, SiO₂ 약 60~70%)보다 SiO₂가 적고 밀도가 큼"],["판 경계","발산 경계는 판이 멀어지는 곳으로 대서양 중앙 해령과 동아프리카 열곡대가 예 · 수렴 경계 중 해양판이 대륙판 아래로 섭입하면 해구와 안데스 산맥 같은 습곡산맥이, 대륙판끼리 충돌하면 히말라야·알프스 산맥이 생김 · 보존 경계(변환 단층)인 산안드레아스 단층에서는 천발지진이 일어남"],["대륙 이동설과 화석","베게너는 대서양 양쪽 해안선의 일치, 같은 화석의 분포, 고생대 말 남반구 여러 대륙의 빙하 흔적, 북아메리카와 유럽 산맥의 지질 구조 연속을 증거로 들었음 · 표준화석은 생존 기간이 짧고 분포 면적이 넓으며 개체수가 많아 지층의 시대를 정하고, 시상화석은 생물이 살던 환경을 알려 줌 · 고생대에는 삼엽충·석탄층·석회암층과 말기 판게아 형성, 중생대에는 공룡, 신생대에는 화폐석이 대표적"],["방사성 연대와 한반도 지층","남은 방사성 원소가 처음의 (½)ⁿ이면 반감기가 n번 지났으므로 ¹⁴C(반감기 5,730년)가 1/4 남은 시료는 약 11,460년 전 것 · 남한의 조선누층군은 고생대 초 해성 석회암층, 평안누층군은 고생대 말~중생대 초 석탄층이며 둘은 부정합 관계이고 그 사이 데본기 지층은 거의 없음 · 경상누층군은 중생대 백악기 육성 퇴적층"]]},{"t":"table","title":"화성암 분류","head":["분류","SiO₂ 함량","암석"],"rows":[["초염기성암","45% 미만","감람암"],["염기성암","45~52%","현무암·반려암"],["중성암","52~63%","안산암·섬록암"],["산성암","63% 이상","유문암·화강암"]]},{"t":"vs","title":"냉각 속도","cols":[{"name":"화산암","items":["마그마가 빨리 식음","결정이 작음(세립질)"]},{"name":"심성암","items":["마그마가 천천히 식음","결정이 큼(조립질)","냉각 속도는 결정 입자 크기를 정함"]}]},{"t":"vs","title":"마그마와 화산","cols":[{"name":"현무암질 마그마","items":["SiO₂가 적고 온도가 높아 점성이 낮음","용암류로 조용히 분출해 경사가 완만한 화산체를 만듦"]},{"name":"유문암질 마그마","items":["SiO₂가 많고 온도가 낮아 점성이 높음","폭발적으로 분출해 화산 쇄설물 비율이 높고 경사가 급한 화산체를 만듦"]}]}],"16":[{"t":"table","title":"천문학","head":["항목","내용"],"rows":[["우리은하 구조","우리은하는 막대 나선은하이고 태양은 원반의 나선팔(오리온 팔 부근)에 있음 · 은하 중심 방향은 궁수자리 쪽 · 나선팔에는 젊은 별과 성운이 많고, 헤일로에는 늙은 별로 된 구상성단이 분포"],["우리은하 관측과 회전","성간 티끌에 가려진 원반 구조는 중성수소가 내는 21 cm 전파로 알아냄 · 우리은하의 회전 속도는 중심에서 수백 pc까지 급히 커진 뒤 바깥쪽에서 거의 일정하게 유지되며, 이는 보이지 않는 암흑물질이 있다는 근거 · 오리온자리 말머리성운은 우리은하 안의 암흑성운"],["태양","태양은 고온으로 이온화된 플라스마 상태 · 내부는 핵, 복사층, 대류층으로 이루어져 깊이에 따라 온도와 밀도가 다르며, 핵에서 수소 핵융합(양성자-양성자 연쇄 반응)이 일어남 · 표면은 광구이고 그 바깥에 채층과 코로나가 있음"],["목성형 행성","목성형 행성은 수소, 헬륨, 수소 화합물이 주성분 · 질량과 자기장 세기가 가장 큰 것은 목성, 평균 밀도가 가장 작은 것은 토성(약 0.69 g/cm³로 물보다 작음) · 천왕성과 해왕성은 대기의 메탄이 붉은빛을 흡수해 푸르게 보임"]]},{"t":"vs","title":"일식과 월식","cols":[{"name":"일식","items":["태양-달-지구 순으로 늘어선 삭일 때 일어남"]},{"name":"월식","items":["태양-지구-달 순으로 늘어선 망일 때 일어남"]}]},{"t":"def","term":"달의 공전 궤도면","text":"달의 공전 궤도면이 황도면에 약 5° 기울어 있어 삭과 망 때마다 식이 일어나지는 않는다"},{"t":"table","title":"별과 우주의 관계식","head":["법칙","내용"],"rows":[["케플러 제3법칙","공전주기의 제곱이 궤도 긴반지름의 세제곱에 비례(P² ∝ a³)"],["빈의 법칙","λ_max·T = 일정에 따라 표면 온도가 높은 별일수록 최대 복사 파장이 짧음"],["슈테판-볼츠만 법칙","별의 광도는 L = 4πR²σT⁴"],["허블 법칙","v = H₀d"]]}]};
