(window.TNQ=window.TNQ||[]).push({"terms":{"충격량":{"d":"물체가 받는 힘에 작용 시간을 곱한 양으로, 운동량의 변화량과 같다.","r":["운동량"]},"운동량":{"d":"질량과 속도의 곱으로, 외력이 없으면 충돌 전후에 총합이 보존된다.","r":["충격량"]},"구심력":{"d":"원운동하는 물체를 원의 중심 쪽으로 당기는 알짜힘이다.","r":["구심가속도"]},"구심가속도":{"d":"등속 원운동에서 속력은 일정해도 방향이 바뀌며 생기는, 중심을 향한 가속도이다.","r":["구심력"]},"관성모멘트":{"d":"회전 운동에서 물체가 각속도 변화에 저항하는 정도를 나타내는 양이다.","r":["회전 운동에너지"]},"회전 운동에너지":{"d":"회전하는 물체가 가진 운동에너지로 관성모멘트와 각속도로 정해진다.","r":["관성모멘트"]},"단진자":{"d":"줄에 매달린 추가 작은 각도로 왕복하는 장치로, 주기가 줄 길이와 중력가속도로 정해진다.","r":[]},"내부에너지":{"d":"기체를 이루는 분자들의 운동에너지와 위치에너지를 합한 에너지이다.","r":["이상기체"]},"이상기체":{"d":"분자 크기와 분자 사이 힘을 무시하고 상태방정식을 완전히 따른다고 보는 가상의 기체이다.","r":["내부에너지"]},"단열팽창":{"d":"열의 출입 없이 기체가 팽창하는 과정으로, 내부에너지가 줄어 온도가 내려간다.","r":[]},"카르노 기관":{"d":"두 열원 사이에서 작동하는 이상적인 가역 열기관으로 같은 조건의 기관 중 효율이 가장 높다.","r":["엔트로피"]},"엔트로피":{"d":"계의 무질서한 정도를 나타내는 양으로, 고립계에서는 감소하지 않는다.","r":["카르노 기관"]},"솔레노이드":{"d":"도선을 원통 모양으로 촘촘히 감은 코일로, 전류를 흘리면 내부에 거의 균일한 자기장이 생긴다.","r":[]},"로런츠 힘":{"d":"자기장 속에서 운동하는 전하가 받는 힘으로 속도와 자기장에 모두 수직이다.","r":[]},"렌츠 법칙":{"d":"유도전류가 원래 자속의 변화를 방해하는 방향으로 흐른다는 법칙이다.","r":["패러데이 법칙"]},"패러데이 법칙":{"d":"유도기전력의 크기가 자기선속의 시간 변화율에 비례한다는 법칙이다.","r":["렌츠 법칙"]},"변위전류":{"d":"시간에 따라 변하는 전기장이 만드는 가상의 전류로 자기장을 유도한다.","r":[]},"정상파":{"d":"진행 방향이 반대인 두 파동이 겹쳐 마디와 배가 제자리에 고정된 것처럼 보이는 파동이다.","r":[]},"임계각":{"d":"굴절률이 큰 매질에서 작은 매질로 갈 때 전반사가 시작되는 최소의 입사각이다.","r":["전반사"]},"전반사":{"d":"빛이 임계각보다 큰 각으로 입사해 경계면에서 전부 반사되는 현상이다.","r":["임계각"]},"이중슬릿":{"d":"좁은 틈 두 개를 지난 빛이 겹쳐 밝고 어두운 무늬를 만드는 간섭 실험 장치이다.","r":[]},"질량결손":{"d":"핵반응에서 줄어든 질량으로, 아인슈타인의 관계식에 따라 에너지로 방출된다.","r":[]},"고유시간":{"d":"어떤 사건이 일어나는 곳에 함께 있는 관측자가 재는 시간 간격이다.","r":["고유길이"]},"고유길이":{"d":"물체와 같은 관성계에 있는 관측자가 재는 물체의 길이이다.","r":["고유시간"]},"광전효과":{"d":"금속에 일정 진동수 이상의 빛을 쬘 때 전자가 튀어나오는 현상이다.","r":["일함수"]},"일함수":{"d":"금속 표면에서 전자 하나를 떼어 내는 데 필요한 최소 에너지이다.","r":["광전효과"]},"물질파":{"d":"입자가 가지는 파동성으로, 파장이 플랑크 상수를 운동량으로 나눈 값이다.","r":[]},"결합 차수":{"d":"결합성 전자 수와 반결합성 전자 수의 차이의 절반으로 결합의 세기를 나타낸다.","r":["상자기성"]},"홀전자":{"d":"오비탈에서 짝을 이루지 못하고 혼자 있는 전자이다.","r":["상자기성"]},"상자기성":{"d":"홀전자가 있어 외부 자기장 쪽으로 끌리는 성질이다.","r":["반자기성","홀전자"]},"반자기성":{"d":"모든 전자가 쌍을 이루어 자기장에서 약하게 밀려나는 성질이다.","r":["상자기성"]},"기하이성질체":{"d":"원자 연결 순서는 같지만 공간 배열이 달라 생기는 이성질체이다.","r":[]},"결정장 안정화 에너지":{"d":"리간드 장에서 d 오비탈이 갈라질 때 전자 배치로 얻는 에너지 이득이다.","r":[]},"호변이성질화":{"d":"수소 원자와 이중결합 위치가 바뀌어 서로 평형을 이루는 이성질체로 변하는 현상이다.","r":[]},"불포화도":{"d":"분자식에서 구한 고리와 이중결합 수의 합(삼중결합은 둘)으로 수소가 모자란 정도이다.","r":[]},"헨더슨-하셀바흐":{"d":"완충 용액의 pH를 약산의 pKa와 짝염기·약산 농도비로 나타내는 식이다.","r":[]},"공통 이온 효과":{"d":"이미 녹아 있는 같은 이온이 있으면 난용성 염의 용해도가 줄어드는 현상이다.","r":[]},"활성화 에너지":{"d":"반응물이 생성물로 바뀌려면 넘어야 하는 에너지 장벽이다.","r":["유효 충돌"]},"속도 결정 단계":{"d":"여러 단계 반응에서 가장 느려 전체 반응 속도를 정하는 단계이다.","r":[]},"유효 충돌":{"d":"활성화 에너지 이상의 에너지와 알맞은 방향을 갖춰 반응으로 이어지는 충돌이다.","r":["활성화 에너지"]},"원핵세포":{"d":"핵막으로 싸인 핵과 막성 소기관이 없는 세포로 세균이 이에 속한다.","r":[]},"펩티드 결합":{"d":"아미노산의 카복실기와 아미노기가 물이 빠지며 이어지는 공유결합이다.","r":[]},"해당과정":{"d":"세포질에서 포도당을 피루브산으로 분해하며 ATP를 얻는 단계이다.","r":[]},"명반응":{"d":"틸라코이드에서 빛에너지로 물을 분해해 ATP와 NADPH를 만드는 광합성 단계이다.","r":["캘빈 회로"]},"캘빈 회로":{"d":"스트로마에서 CO₂를 고정해 당을 만드는 광합성의 탄소 고정 반응이다.","r":["명반응"]},"화학삼투":{"d":"막 사이 수소 이온 농도 기울기를 이용해 ATP를 합성하는 방식이다.","r":[]},"항원제시세포":{"d":"항원을 MHC II에 실어 T세포에 보여 주는 면역세포이다.","r":["에피토프"]},"에피토프":{"d":"항원 표면에서 항체나 수용체가 직접 결합하는 부위인 항원결정부이다.","r":[]},"동형전환":{"d":"B세포가 항원 특이성은 그대로 두고 항체의 종류를 바꾸는 과정이다.","r":[]},"난할":{"d":"수정란이 세포 성장 없이 빠르게 분열해 세포 수를 늘리는 초기 발생 과정이다.","r":[]},"오카자키 절편":{"d":"DNA 복제에서 지연가닥이 불연속적으로 합성돼 생기는 짧은 DNA 조각이다.","r":[]},"프로모터":{"d":"RNA 중합효소가 결합해 전사를 시작하는 DNA 염기서열이다.","r":["오페론"]},"오페론":{"d":"원핵생물에서 하나의 프로모터로 함께 조절되는 유전자들의 묶음이다.","r":["프로모터"]},"스플라이싱":{"d":"전사된 RNA에서 인트론을 잘라 내고 엑손을 이어 붙이는 가공이다.","r":[]},"침묵 돌연변이":{"d":"염기가 바뀌어도 코돈이 같은 아미노산을 지정해 단백질이 달라지지 않는 돌연변이이다.","r":[]},"뉴클레오솜":{"d":"DNA가 히스톤 단백질 덩어리를 감고 있는 염색질의 기본 단위이다.","r":[]},"접합":{"d":"세균이 선모로 연결돼 플라스미드 같은 DNA를 직접 전달하는 과정이다.","r":[]},"유전자 부동":{"d":"우연에 의해 집단의 대립유전자 빈도가 무작위로 변하는 현상이다.","r":[]},"중복수정":{"d":"속씨식물에서 정핵 둘이 각각 난세포와 극핵과 만나는 두 번의 수정이다.","r":[]},"열염순환":{"d":"수온과 염분 차에 따른 밀도 차로 일어나는 해수의 심층 순환이다.","r":[]},"진원":{"d":"지진이 처음 발생한 땅속 지점이다.","r":["진앙"]},"진앙":{"d":"진원 바로 위에 있는 지표면의 지점이다.","r":["진원"]},"섭입":{"d":"밀도가 큰 해양판이 다른 판 아래로 파고들어 가는 현상이다.","r":[]},"표준화석":{"d":"지층의 시대를 정하는 데 쓰이는, 생존 기간이 짧고 널리 분포한 화석이다.","r":[]},"저속도층":{"d":"상부 맨틀에서 지진파 속도가 느려지는 층이다.","r":[]},"암흑물질":{"d":"빛을 내지 않아 보이지 않지만 중력으로 존재가 추정되는 물질이다.","r":[]}},"notes":{"1.0×10⁻⁸ M 염산은 물의 자동이온화를 무시할 수 없어 전하 균형 [H⁺] = [Cl⁻] + [OH⁻]로 풀며, [H⁺] ≈ 1.05×10⁻⁷ M, pH ≈ 6.98":"농도가 매우 낮으면 물의 자동이온화가 무시되지 않아 전하 균형식으로 풀어야 하고, 그래서 pH가 중성에 아주 가깝게 나옵니다.","1/[A] = 1/[A]₀ + kt":"이차 반응은 농도의 역수가 시간에 비례해 커지는 적분 속도식을 따릅니다.","25℃에서 E = E° - (0.0592/n)log Q이고 ΔG° = -nFE°":"25℃에서 네른스트 식은 표준 전위에 반응 지수의 로그 항을 보정해 전위를 구하고, 표준 깁스 에너지 변화는 표준 전위에 비례합니다.","25℃에서 Kw = [H⁺][OH⁻] = 1.0×10⁻¹⁴이고 pH + pOH = 14":"25℃에서 물의 이온곱 상수는 1.0×10⁻¹⁴이어서 pH와 pOH를 더하면 14입니다.","2주기 동핵 이원자 분자 중 B₂, C₂, N₂는 π₂p가 σ₂p보다 낮고, O₂, F₂는 σ₂p가 π₂p보다 낮음":"2주기 동핵 이원자 분자는 전자 수에 따라 σ와 π 궤도의 에너지 순서가 뒤바뀌며 그 경계가 N₂와 O₂ 사이에 있습니다.","2차 구조에서 α 구조는 나선, β 구조는 병풍 모양":"2차 구조는 수소 결합으로 생긴 규칙적인 접힘이며, 나선 모양이 알파 구조이고 병풍 모양이 베타 구조입니다.","50% 해리이면 pH = pKa, 약 91% 해리이면 [A⁻]/[HA] ≈ 10이라 pH = pKa + 1":"절반이 해리되면 농도비가 같아 pH가 pKa와 같고, 약 91% 해리되면 농도비가 10이라 pH가 1만큼 높아집니다.","600 K와 300 K 사이면 0.5":"고온 열원 600 K, 저온 열원 300 K이면 온도 비가 절반이라 효율이 0.5입니다.","A(s) ⇄ B(g) + C(g)의 Kp = P_B·P_C":"고체는 식에서 빠지므로 기체 생성물 둘의 부분 압력의 곱이 이 반응의 압력 평형 상수가 됩니다.","BF₃는 평면 삼각형, CH₄와 C₂H₆의 탄소는 sp³":"삼불화붕소는 중심 원자가 세 방향으로 결합하는 평면 삼각형이고, 메테인과 에테인의 탄소는 sp³ 혼성입니다.","B₂(π₂p에 홀전자 2)와 O₂(π*₂p에 홀전자 2)는 상자기성, C₂, N₂, F₂는 반자기성":"홀전자가 있으면 상자기성이고 모두 쌍이면 반자기성이어서, B₂와 O₂는 상자기성, 나머지는 반자기성입니다.","B₂의 LUMO는 결합성 σ₂p":"LUMO는 전자가 채워지지 않은 가장 낮은 궤도이며, B₂에서는 결합성 σ₂p 궤도가 그 자리입니다.","B세포 수용체와 항체는 항원 표면의 항원결정부(에피토프)를 인식":"B세포 수용체와 항체가 인식하는 부위는 항원 표면의 에피토프라 불리는 항원결정부입니다.","C=O 신축 진동은 IR 스펙트럼 1700~1750 cm⁻¹ 부근에서 강하게 나타남":"카보닐기의 C=O 신축 진동은 적외선 흡수 스펙트럼에서 1700~1750 cm⁻¹ 부근에 강한 흡수띠로 나타납니다.","Cl₂/FeCl₃은 클로로벤젠, HNO₃/H₂SO₄는 나이트로벤젠, CH₃Cl/AlCl₃(프리델-크래프츠 알킬화)는 톨루엔을 만듦":"시약에 따라 고리에 붙는 원자단이 달라져, 염소화·나이트로화·알킬화가 각각 클로로벤젠·나이트로벤젠·톨루엔을 만듭니다.","C₄H₈O와 C₆H₁₂O는 불포화도가 1이므로 고리 하나 또는 C=C·C=O 하나를 가짐":"불포화도가 1이면 고리나 C=C, C=O 중 한 가지만 있다는 뜻이므로 가능한 구조가 그 범위로 좁혀집니다.","C₄H₈O 중 알코올을 뺀 고리형은 산소가 고리에 든 6개(테트라하이드로퓨란, 옥세테인 2개, 옥시레인 3개)와 메톡시사이클로프로페인을 합해 7개":"C₄H₈O의 고리형 구조를 산소가 고리 안에 있는 경우와 바깥에 있는 경우로 나누어 세면 모두 7개가 됩니다.","C₆H₁₂O의 케톤은 2-헥산온, 3-헥산온, 3-메틸-2-펜탄온, 4-메틸-2-펜탄온, 2-메틸-3-펜탄온, 3,3-다이메틸-2-뷰탄온의 6개":"케톤이 될 수 있는 탄소 골격의 경우를 빠짐없이 세어 보면 모두 6개이며, 이름 붙인 여섯 가지가 그것입니다.","DNA는 음전하라 겔 전기영동에서 양극으로 이동":"DNA는 인산기 때문에 음전하를 띠어 겔 전기영동에서 양극 쪽으로 이동합니다.","DNA 복제는 분열 전 간기 S기에 한 번만 일어남":"DNA 복제는 분열 전에 간기의 S기에서 한 번만 일어나므로 분열 때마다 복제가 되풀이되는 것은 아닙니다.","H⁺ 농도가 줄면(pH 증가) 수소 전극 쪽 환원 전위가 낮아져 전지 전위가 작아짐":"H⁺ 농도가 낮아지면 수소 전극의 환원 전위가 내려가 전체 전지 전위가 작아집니다.","MA₄B₂형과 MA₃B₃형은 기하이성질체가 각각 2개(cis·trans, fac·mer)":"이 두 형태는 리간드 배열에 따라 시스-트랜스 또는 fac-mer라는 두 가지 기하이성질체가 존재합니다.","MHC I은 거의 모든 유핵세포에, MHC II는 항원제시세포에 있으며 항원제시세포는 둘 다 가짐":"MHC I은 거의 모든 유핵세포에 있고 MHC II는 항원제시세포에만 있어, 항원제시세포는 두 종류를 모두 가집니다.","MnO₄⁻는 산성에서 Mn²⁺(전자 5개 받음), 염기성·중성에서 MnO₂(전자 3개 받음)":"과망간산 이온은 산성에서는 전자 5개를 받아 Mn²⁺로, 염기성이나 중성에서는 전자 3개를 받아 MnO₂로 환원됩니다.","Mn²⁺(d⁵) 고스핀은 e²t₂³이라 안정화 에너지가 0이고 홀전자가 5개":"d 오비탈에 전자가 다섯 개이고 고스핀이면 낮춰진 에너지와 높아진 에너지가 상쇄되어 안정화 에너지가 0입니다.","NO는 가전자 11개로 홀전자 1개를 가짐":"NO는 가전자가 홀수인 11개라 짝을 못 이룬 홀전자 1개가 남아 상자기성입니다.","N₂의 HOMO는 σ₂p, O₂와 F₂의 HOMO는 π*₂p":"가장 높은 에너지의 전자가 채워진 궤도(HOMO)가 N₂는 시그마 결합성 궤도, O₂와 F₂는 파이 반결합성 궤도입니다.","PEP 카르복실화효소로 CO₂를 모아 유관속초세포의 캘빈 회로로 보내 광호흡 손실이 적음":"C₄ 식물은 PEP 카르복실화효소로 CO₂를 먼저 모아 유관속초세포로 보내므로 광호흡 때문에 잃는 양이 적습니다.","P파는 진행 방향과 진동 방향이 나란한 종파로 고체·액체를 모두 통과하고 S파보다 빠르며, S파는 횡파로 고체만 통과":"P파는 종파로 고체와 액체를 통과하고 속도가 빠르며, S파는 횡파로 고체만 통과하고 느립니다.","P파와 S파는 실체파이고, 두 파의 도착 시간 차(PS시)는 진앙 거리가 멀수록 커짐":"P파와 S파는 지구 내부를 통과하는 실체파이며, 두 파의 도착 시간 차인 PS시는 진앙에서 멀수록 큽니다.","RNA 중합효소가 결합해 전사를 시작하는 DNA 서열이 프로모터이고, 진핵세포는 RNA 중합효소 I, II, III이 RNA를 나누어 합성":"프로모터는 RNA 중합효소가 붙어 전사를 개시하는 자리이며, 진핵세포는 세 종류의 RNA 중합효소가 RNA 종류를 나누어 만듭니다.","SiO₂가 많고 온도가 낮아 점성이 높음":"유문암질 마그마는 SiO₂가 많고 온도가 낮아 점성이 높습니다.","SiO₂가 적고 온도가 높아 점성이 낮음":"현무암질 마그마는 SiO₂가 적고 온도가 높아 흐름에 대한 저항인 점성이 낮습니다.","TCA 회로는 미토콘드리아 기질에서 일어남":"TCA 회로가 일어나는 장소는 미토콘드리아의 기질입니다.","T세포는 골수에서 만들어져 흉선에서 성숙하고, B세포는 골수에서 성숙":"T세포는 골수에서 만들어져 흉선에서 성숙하는 반면 B세포는 만들어진 골수에서 그대로 성숙합니다.","W = -ΔU이므로 단열팽창하면 온도가 내려감":"단열 과정에서는 열 출입이 없어 기체가 한 일만큼 내부에너지가 줄므로, 팽창하면 온도가 내려갑니다.","[A] = [A]₀ - kt로 농도가 시간에 따라 일정하게 줄어듦":"영차 반응은 농도와 무관하게 속도가 일정해 농도가 시간에 비례해 직선으로 줄어듭니다.","[M(AA)₂B₂]형의 cis 이성질체는 거울상과 겹치지 않아 광학 활성":"시스형은 거울상과 겹쳐지지 않는 키랄성이 있어 편광면을 돌리는 광학 활성을 가집니다.","cAMP-CAP 복합체에 의한 양성 조절":"젖당 오페론의 양성 조절은 cAMP와 CAP이 복합체를 이뤄 전사를 촉진하는 방식입니다.","e = W/Q_H = 1 - Q_C/Q_H":"열기관 효율은 한 일을 흡수한 열로 나눈 값이며, 저열원에 버린 열의 비율을 빼서도 구합니다.","h에서 정지 출발해 h/2 지점을 지나면 내려온 높이가 h/2이므로 v = √(gh)":"내려온 높이가 처음 높이의 절반이므로 속력 식의 높이에 그 절반을 넣어 구한 값입니다.","k가 3배이면 파장은 1/3배이고, ω가 2배·k가 3배이면 속력은 2/3배":"파수가 커지면 파장이 그 비율만큼 줄고, 속력은 각진동수 배수를 파수 배수로 나눈 값입니다.","ln[A] = ln[A]₀ - kt":"일차 반응에서는 농도의 자연로그가 시간에 대해 일정한 비율로 줄어드는 적분 속도식을 따릅니다.","ln[A]를 시간에 대해 그리면 기울기 -k인 직선":"농도의 자연로그를 시간에 대해 그리면 직선이 되고 그 기울기의 크기가 속도 상수입니다.","ln k를 1/T에 대해 그리면 기울기 -Ea/R인 직선":"속도 상수의 자연로그를 절대온도의 역수에 대해 그리면 직선이 되고, 기울기로 활성화 에너지를 구합니다.","n = 3에서 n = 1로 전이할 때 방출 광자 에너지는 E₃ - E₁ = 8E₁":"에너지가 양자수 제곱에 비례하므로 n이 3이면 바닥 에너지의 아홉 배이고, 둘의 차인 8E₁이 방출 광자 에너지입니다.","pH = pKa + log([A⁻]/[HA])(헨더슨-하셀바흐)":"완충 용액의 pH는 약산의 pKa에 짝염기와 약산 농도비의 로그를 더한 값이며 헨더슨-하셀바흐 식이라 합니다.","t½ = 0.693/k는 처음 농도와 관계없음":"일차 반응의 반감기는 속도 상수만으로 정해져 처음 농도에 상관없이 일정합니다.","t½ = 1/(k[A]₀)는 처음 농도에 반비례":"이차 반응은 처음 농도가 클수록 반응이 빨라 반감기가 짧아져, 반감기가 처음 농도에 반비례합니다.","t½ = [A]₀/(2k)는 처음 농도에 비례":"영차 반응의 반감기는 처음 농도가 클수록 길어, 반감기가 처음 농도에 비례합니다.","v = 0.6c이면 γ = 1.25":"빛 속력의 0.6배일 때 로런츠 인자가 1.25가 되는 예이며, 시간 지연과 길이 수축 계산에 쓰입니다.","v = v₀ + at, s = v₀t + ½at², v² - v₀² = 2as로 푼다":"시간·속도·변위·가속도를 잇는 등가속도 운동의 세 식이며, 시간이 주어지지 않아도 마지막 식으로 풀 수 있습니다.","y = A sin(kx - ωt)에서 진폭은 A, 파장 λ = 2π/k, 주기 T = 2π/ω":"사인파 식에서 앞의 계수가 진폭이고, 파수와 각진동수로부터 파장과 주기가 각각 구해집니다.","²H + ³H → ⁴He + n + 17.6 MeV(D-T 핵융합)에서 2 + 3 = 4 + 1":"중수소와 삼중수소가 헬륨과 중성자로 바뀌는 식으로, 윗첨자 질량수 합이 양쪽에서 같아 보존이 확인됩니다.","γ = 1/√(1 - v²/c²)일 때 고유시간 Δt₀는 상대 운동하는 관측자에게 γΔt₀로 길어지고, 고유길이 L₀는 운동 방향으로 L₀/γ로 짧아짐":"상대 운동하는 관측자에게는 고유시간이 로런츠 인자배로 늘어나고 운동 방향의 고유길이는 그 비율로 줄어듭니다.","λ_max·T = 일정에 따라 표면 온도가 높은 별일수록 최대 복사 파장이 짧음":"빈의 법칙은 최대 복사 세기의 파장과 표면 온도의 곱이 일정하다는 것으로, 뜨거운 별일수록 짧은 파장에서 가장 밝습니다.","π 결합이 사슬 전체로 이어진 trans-폴리아세틸렌은 도핑하면 전도성 고분자가 됨":"이중결합이 사슬 전체로 번갈아 이어진 공액 구조라 도핑하면 전하가 이동해 전도성을 띠게 됩니다.","가역과정의 엔트로피 변화는 ΔS = Q/T이고, 고립계의 엔트로피는 줄어들지 않음":"가역과정에서는 흡수한 열을 온도로 나눈 값이 엔트로피 변화이며, 고립계 전체의 엔트로피는 감소하지 않습니다.","가이드 RNA가 표적을 안내해야 Cas9이 DNA를 자름":"Cas9은 가이드 RNA가 표적 DNA 서열을 찾아 안내해 주어야 그 자리를 자를 수 있습니다.","가전자가 10개인 N₂, CO, CN⁻, NO⁺는 결합 차수 3이고 반자기성":"전자 수가 같은 등전자 화학종은 궤도 배치가 같아 결합 차수 3과 반자기성이 같습니다.","감람석, 휘석, 각섬석, 흑운모, 장석, 석영은 규산염 광물":"감람석부터 석영까지의 광물은 규소와 산소를 기본 단위로 하는 규산염 광물에 속합니다.","감쇠 조절 · 감쇠는 전사와 번역이 동시에 일어나는 원핵생물에서만 가능":"감쇠 조절은 전사와 번역이 동시에 일어나는 원핵생물에서만 가능한데, 이는 핵막이 없어 두 과정이 맞물리기 때문입니다.","감수분열 딸세포는 교차와 독립 분배로 유전적으로 서로 다름":"교차와 염색체의 독립 분배 덕분에 감수분열로 만든 딸세포는 유전적으로 서로 다릅니다.","감수분열은 2회 분열로 딸세포 4개를 만들며, 감수분열 I 전기에 상동염색체가 접합해 교차가 일어나고 감수분열 II에서 자매염색분체가 분리됨":"감수분열은 두 번 분열해 딸세포가 네 개 생기며, 첫 분열에서 상동염색체가 접합·교차한 뒤 갈라지고 둘째 분열에서 자매염색분체가 갈라집니다.","같은 v₀에서 출발해 멈추면 이동 거리는 정지까지 걸린 시간에 비례":"정지할 때까지의 평균 속력이 처음 속력의 절반으로 같으므로 이동 거리는 걸린 시간에 정비례합니다.","같은 두 열원 사이의 어떤 기관도 카르노 기관보다 효율이 높을 수 없고, 효율 1인 기관은 없음":"카르노 기관이 같은 열원 사이의 최대 효율이며, 열을 전부 일로 바꾸는 완전한 기관은 제이법칙상 불가능합니다.","같은 염색체에 있는 유전자는 교차가 없으면 함께 전달됨":"같은 염색체 위의 유전자는 교차가 없는 한 한 덩어리로 묶여 같은 배우자로 함께 전달됩니다.","같은 이온을 넣으면 용해도가 줄어듦(공통 이온 효과)":"이미 녹아 있는 같은 이온이 평형을 역반응 쪽으로 밀어 침전이 늘기 때문에 용해도가 줄어드는 공통 이온 효과입니다.","같은 파장이면 광자 에너지 hc/λ가 전자 운동에너지보다 훨씬 큼":"같은 파장일 때 광자 에너지는 파장에 반비례하지만 전자 운동에너지는 파장 제곱에 반비례해 광자 쪽이 훨씬 큽니다.","개구리 알은 난황이 많아도 알 전체가 갈라지는 전할(불균등 전할)이고, 조류 알은 부분할을 함":"난황이 많은 개구리 알도 알 전체가 갈라지는 전할이지만 크기가 고르지 않은 불균등 전할이고, 조류 알은 일부만 갈라지는 부분할입니다.","결정장 안정화 에너지는 e 전자 하나당 -0.6Δt, t₂ 전자 하나당 +0.4Δt":"e 전자는 에너지를 낮추고 t₂ 전자는 높여, 전자 배치에 따른 안정화 정도를 합산한 값이 결정장 안정화 에너지입니다.","결합 차수 = (결합성 전자 수 - 반결합성 전자 수)/2":"결합 차수는 결합성 전자 수에서 반결합성 전자 수를 뺀 값의 절반으로, 결합의 세기를 나타냅니다.","결합 차수는 Li₂ 1, B₂ 1, C₂ 2, N₂ 3, O₂ 2, F₂ 1이고 결합 에너지는 N₂가 가장 큼":"결합 차수가 클수록 결합이 강해서 N₂의 결합 차수 3이 가장 커 결합 에너지도 가장 큽니다.","경상누층군은 중생대 백악기 육성 퇴적층":"경상누층군은 중생대 백악기에 육지에서 쌓인 퇴적층입니다.","고생대에는 삼엽충·석탄층·석회암층과 말기 판게아 형성, 중생대에는 공룡, 신생대에는 화폐석이 대표적":"지질 시대마다 대표 화석과 사건이 있어 고생대는 삼엽충과 석탄층, 중생대는 공룡, 신생대는 화폐석이 대표적입니다.","고세균과 진핵생물은 히스톤과 결합한 DNA를 가지고 RNA 중합효소가 여러 종류":"세균과 달리 고세균과 진핵생물은 DNA가 히스톤과 결합해 있고 RNA 중합효소도 여러 종류입니다.","고온에서 먼저 정출되는 광물일수록 Mg·Fe·Ca가 많고 어두우며, 저온의 정장석·백운모·석영은 밝음":"고온에서 먼저 정출되는 광물에는 Mg·Fe·Ca가 많아 어둡고, 저온에서 정출되는 광물은 밝은색입니다.","고위도에서 차갑고 짠 표층수가 가라앉아 심층수가 되며, 심해의 해수를 섞음":"고위도에서 차갑고 염분이 높아 무거워진 표층수가 가라앉아 심층수가 되고 심해의 바닷물을 순환시킵니다.","곤충 외골격·갑각류 껍질·곰팡이 세포벽의 키틴은 N-아세틸글루코사민 다당류이고, 콜라겐은 단백질":"키틴은 곤충·갑각류 외골격과 곰팡이 세포벽을 이루는 질소 함유 다당류이고, 콜라겐은 다당류가 아닌 단백질입니다.","골수에서 자기 항원에 강하게 반응하는 미성숙 B세포는 세포자멸사로 제거됨":"자기 항원에 강하게 반응하는 미성숙 B세포는 세포자멸사로 없애져 자기 몸을 공격하지 않게 됩니다.","공동억제자인 트립토판이 결합한 억제자가 작동자에 붙어 전사를 막는 음성 조절":"트립토판 오페론에서는 트립토판이 공동억제자로 억제자와 결합해 작동자에 붙어 전사를 막는 음성 조절이 일어납니다.","공전주기의 제곱이 궤도 긴반지름의 세제곱에 비례(P² ∝ a³)":"행성의 공전주기를 제곱하면 궤도 긴반지름의 세제곱에 비례한다는 케플러의 세 번째 법칙입니다.","관성모멘트는 얇은 고리 MR², 원판·속찬 원기둥 ½MR², 속찬 구 ⅖MR²":"관성모멘트의 계수는 모양에 따라 다르며, 질량이 바깥에 몰린 고리가 가장 크고 속찬 구가 가장 작습니다.","광계 II에서 들뜬 전자의 에너지로 H⁺ 농도 기울기가 생겨 ATP가 합성되고, 최종 전자수용체 NADP⁺가 NADPH가 됨":"광계 II에서 들뜬 전자가 수소 이온 농도 기울기를 만들어 ATP를 합성하고, 마지막에 NADP⁺가 전자를 받아 NADPH가 됩니다.","광인산화와 산화적 인산화는 모두 화학삼투로 ATP를 만듦":"광인산화와 산화적 인산화는 모두 막을 사이에 둔 수소 이온의 농도 기울기를 이용하는 화학삼투로 ATP를 합성합니다.","광자 에너지는 E = hf = hc/λ이고 hc ≈ 1240 eV·nm이므로 E(eV) ≈ 1240/λ(nm)":"광자 에너지는 진동수에 비례하고 파장에 반비례하며, 상수 곱 값을 쓰면 전자볼트 단위로 파장만으로 계산됩니다.","광전효과에서 튀어나온 전자의 최대 운동에너지는 K_max = hf - W(W 일함수)이고, 빛의 세기가 아니라 진동수가 문턱값을 넘어야 전자가 나옴":"광전효과는 진동수가 문턱값을 넘어야 일어나며, 전자의 최대 운동에너지는 광자 에너지에서 일함수를 뺀 값입니다.","굴러가는 얇은 고리는 병진·회전 에너지가 같아 전체 운동에너지가 Mv²":"굴러가는 얇은 고리는 병진과 회전 에너지가 같아 합이 병진 운동에너지의 두 배가 됩니다.","굴절률 n = c/v이고 스넬 법칙은 n₁sinθ₁ = n₂sinθ₂":"굴절률은 진공 속 빛의 속력과 매질 속 속력의 비이며, 스넬 법칙은 경계에서 굴절률과 각의 사인의 곱이 같다는 것입니다.","굴절률이 큰 매질에서 작은 매질로 갈 때 입사각이 임계각(sinθc = n₂/n₁)보다 크면 전반사가 일어남":"전반사는 빛이 굴절률 큰 쪽에서 작은 쪽으로 가며 입사각이 임계각을 넘을 때 경계에서 전부 반사되는 현상입니다.","균일한 전기장에서 전위차는 V = Ed":"균일한 전기장에서는 전위차가 전기장 세기와 거리의 곱으로 간단히 구해집니다.","기울기가 급해 적운형 구름(적란운)과 소나기가 생김":"한랭 전선면은 경사가 가팔라 적운형 구름이 솟아 소나기가 내리는 전선입니다.","기울기가 완만해 층운형 구름(난층운)이 넓게 생기고 지속적인 비가 내림":"온난 전선면은 경사가 완만해 층운형 구름이 넓게 퍼지고 비가 오래 이어지는 전선입니다.","기체가 한 일은 P-V 그래프 아래 넓이이며 등압과정에서는 W = PΔV":"압력-부피 그래프에서 곡선 아래 넓이가 일이며, 압력이 일정한 등압과정에서는 압력과 부피 변화의 곱입니다.","기체가 흡수한 열 Q = 내부에너지 변화 ΔU + 기체가 한 일 W":"열역학 제일법칙은 흡수한 열이 내부에너지 증가와 기체가 외부에 한 일로 나뉜다는 에너지 보존입니다.","긴 직선 도선에서 거리 r인 곳의 자기장은 B = μ₀I/(2πr)이고, 단위 길이당 감은 수 n인 솔레노이드 내부는 B = μ₀nI":"직선 도선의 자기장은 거리에 반비례하고, 솔레노이드 내부 자기장은 단위 길이당 감은 수와 전류에 비례합니다.","나선팔에는 젊은 별과 성운이 많고, 헤일로에는 늙은 별로 된 구상성단이 분포":"젊은 별과 성운은 원반의 나선팔에 많고, 늙은 별로 이루어진 구상성단은 헤일로에 분포합니다.","나이트로벤젠(약 211℃)은 톨루엔(약 111℃)보다 끓는점이 높음":"나이트로벤젠이 톨루엔보다 끓는점이 높은 것은 극성이 큰 나이트로기 때문에 분자 사이 인력이 더 크기 때문입니다.","난용성 염 AB(s) ⇄ A⁺ + B⁻(Ksp)와 착이온 형성 A⁺ + 3CN⁻ ⇄ A(CN)₃²⁻(Kf)을 더한 전체 반응의 평형 상수는 K = Ksp·Kf":"두 평형을 더한 반응의 평형 상수는 각 평형 상수를 곱한 값이어서, 착이온 형성은 겉보기 용해 평형 상수를 키웁니다.","난할 중 세포주기는 G₁, G₂가 거의 없이 S기와 M기만 반복되어 세포가 작아짐":"난할에서는 세포가 자라는 G₁과 G₂기가 거의 없이 S기와 M기만 반복돼 세포 크기가 점점 작아집니다.","난황이 몰린 쪽이 식물극, 반대쪽이 동물극":"난황이 몰려 있는 쪽을 식물극이라 하고 그 반대쪽을 동물극이라 합니다.","날씨는 특정 시간·장소의 대기 상태이고 기후는 장기간의 평균 상태이며 기온·강수량·바람·기압이 기후요소":"날씨는 어느 때 어느 곳의 대기 상태이고 기후는 오랜 기간의 평균이며, 기온·강수량·바람·기압이 그 구성 요소입니다.","남은 방사성 원소가 처음의 (½)ⁿ이면 반감기가 n번 지났으므로 ¹⁴C(반감기 5,730년)가 1/4 남은 시료는 약 11,460년 전 것":"방사성 원소가 반감기를 두 번 지나면 처음의 1/4이 남으므로 5,730년의 두 배인 약 11,460년 전 시료입니다.","남은 양은 N = N₀(½)^(t/T)(T 반감기)":"반감기가 한 번 지날 때마다 남은 양이 절반이 되므로, 남은 양은 처음 양에 절반을 경과 시간 비율만큼 거듭제곱한 값입니다.","남한의 조선누층군은 고생대 초 해성 석회암층, 평안누층군은 고생대 말~중생대 초 석탄층이며 둘은 부정합 관계이고 그 사이 데본기 지층은 거의 없음":"조선누층군은 바다에서 쌓인 고생대 초 석회암층이고 평안누층군은 고생대 말~중생대 초의 석탄층으로 둘 사이는 부정합입니다.","내부는 핵, 복사층, 대류층으로 이루어져 깊이에 따라 온도와 밀도가 다르며, 핵에서 수소 핵융합(양성자-양성자 연쇄 반응)이 일어남":"태양 내부는 핵, 복사층, 대류층으로 나뉘고 핵에서 양성자-양성자 연쇄 반응으로 수소 핵융합이 일어납니다.","내핵은 압력이 커서 고체이고, 상부 맨틀은 감람암질이며 지진파 속도가 줄어드는 저속도층이 있음":"내핵은 압력이 커 고체이고, 상부 맨틀에는 지진파 속도가 줄어드는 저속도층이 있으며 암석은 감람암질입니다.","냉각 속도는 결정 입자 크기를 정함":"마그마가 식는 속도가 결정이 자랄 시간을 좌우하므로 천천히 식을수록 큰 결정이 만들어집니다.","농도 순서는 [Cl⁻] < [OH⁻] < [H⁺]":"전하 균형상 양이온 농도가 음이온 두 종류의 합이므로 H⁺ 농도가 가장 크고 Cl⁻ 농도가 가장 작습니다.","높이 h만큼 내려온 물체의 속력은 v = √(2gh)이고 질량과 경사각에 관계없음":"줄어든 위치에너지가 전부 운동에너지로 바뀌고 질량은 양변에서 약분되므로 속력은 내려온 높이만으로 정해집니다.","다른 염색체의 유전자는 독립이므로 확률을 곱함":"서로 다른 염색체의 유전자는 독립적으로 분배되므로 각 유전자의 확률을 곱해 전체 확률을 구합니다.","단원자 이상기체의 내부에너지는 U = (3/2)nRT로 온도에만 의존":"단원자 이상기체는 분자 사이 힘이 없어 내부에너지가 온도에만 비례하고 부피나 압력과는 무관합니다.","단일결합만 가진 탄소는 sp³, 이중결합 탄소는 sp², 삼중결합 탄소는 sp":"혼성 궤도는 탄소 둘레의 전자 영역 수로 정해져, 단일·이중·삼중결합 탄소가 차례로 sp³·sp²·sp를 가집니다.","단일 단계(기본 반응)의 차수는 그 단계의 분자 수와 같음":"기본 반응은 실제 충돌 과정을 그대로 나타내므로 반응 차수가 그 단계에 참여하는 분자 수와 같습니다.","달의 공전 궤도면이 황도면에 약 5° 기울어 있어 삭과 망 때마다 식이 일어나지는 않는다":"달의 공전 궤도면이 황도면과 약 5° 어긋나 있어 삭이나 망이 될 때마다 세 천체가 일직선이 되지는 않습니다.","대장균 같은 원핵세포에는 핵막으로 싸인 핵과 미토콘드리아가 없음":"원핵세포는 핵막으로 둘러싸인 핵과 막성 세포소기관인 미토콘드리아가 없는 단순한 구조의 세포입니다.","동형전환은 성숙 B세포가 항체 종류를 바꾸는 과정":"동형전환은 성숙한 B세포가 항원 특이성은 유지한 채 항체의 종류, 곧 불변부를 바꾸는 과정입니다.","두 열원 사이에서 작동하는 가역 카르노 기관의 효율은 e = 1 - T_C/T_H(절대온도)":"가역 카르노 기관의 효율은 두 열원의 절대온도 비로만 정해져서 작동 물질과 무관합니다.","두 점전하 사이의 힘은 F = kq₁q₂/r²이고 전기장은 E = F/q, 점전하의 전기장은 E = kq/r²":"쿨롱 힘은 전하 곱에 비례하고 거리 제곱에 반비례하며, 전기장은 단위 전하당 받는 힘입니다.","등속 원운동의 구심가속도는 v²/r이고 구심력은 mv²/r":"등속 원운동은 속력이 일정해도 방향이 계속 바뀌어 중심 쪽 가속도가 생기며, 이를 일으키는 힘이 구심력입니다.","로런츠 힘 F = qvB를 구심력으로 받아 원운동":"자기장 속에서 전하가 받는 로런츠 힘이 속도에 수직이라 이 힘이 곧 원운동의 구심력 역할을 합니다.","리소좀 효소는 산성(pH 약 5)에서 작용하고, 골지체는 시스 면으로 소포체 소낭을 받아 트랜스 면으로 내보냄":"리소좀의 가수분해 효소는 산성 환경에서 활성을 띠고, 골지체는 시스 면으로 받아 트랜스 면으로 내보내는 방향성이 있습니다.","마찰과 공기저항이 없으면 위치에너지 mgh와 운동에너지 ½mv²의 합이 보존":"마찰과 공기저항이 없을 때 역학적 에너지가 보존되어, 위치에너지가 줄면 그만큼 운동에너지가 늘어납니다.","막으로 싸인 세포소기관과 섬모는 진핵세포의 특징":"막으로 싸인 세포소기관과 섬모는 진핵세포에서만 나타나는 구조적 특징입니다.","만유인력은 F = GMm/r²이고 지표 근처 중력가속도는 g = GM/R²":"만유인력은 두 질량의 곱에 비례하고 거리 제곱에 반비례하며, 지표의 중력가속도는 지구 질량과 반지름으로 정해집니다.","멕시코 만류, 쿠로시오 해류, 캘리포니아 해류, 카나리아 해류는 북반구 아열대 환류이고, 페루(훔볼트) 해류는 남태평양 환류에 속함":"멕시코 만류 등 네 해류는 북반구 아열대 환류의 일부이고, 페루 해류는 남태평양 환류에 속합니다.","명반응은 틸라코이드에서 일어나며 H₂O가 광분해되어 O₂가 나오므로 방출되는 O₂는 CO₂가 아니라 물에서 옴":"명반응에서 물이 광분해되며 산소가 나오기 때문에 광합성이 내놓는 산소는 이산화탄소가 아닌 물에서 유래합니다.","모든 관성계에서 물리법칙과 진공 중 빛의 속력 c는 같고, 어떤 물체도 c보다 빠를 수 없음":"특수상대성이론의 두 가설로, 관성계마다 물리법칙이 같고 진공 중 빛의 속력이 일정하며 물체는 이보다 빠를 수 없습니다.","목성형 행성은 수소, 헬륨, 수소 화합물이 주성분":"목성형 행성은 지구형 행성과 달리 수소, 헬륨과 수소 화합물이 주성분인 거대 행성입니다.","몰농도(M) = 10×밀도(g/mL)×질량 백분율(%)÷몰질량":"몰농도는 용액 한 리터 속 용질의 몰 수이므로 밀도와 질량 백분율에 10을 곱해 몰질량으로 나누어 환산합니다.","물질파 파장은 λ = h/p이고 전자의 운동에너지는 K = p²/(2m) = h²/(2mλ²)":"드브로이 파장은 플랑크 상수를 운동량으로 나눈 값이며, 이를 이용하면 전자 운동에너지를 파장으로 나타낼 수 있습니다.","박테리오파지가 세균 DNA 조각을 옮기는 것":"형질도입은 매개체인 박테리오파지가 감염하는 과정에서 세균 DNA 조각을 다른 세균으로 옮기는 전달입니다.","반응 속도는 v = k[A]ᵐ[B]ⁿ으로 나타내고 반응 차수 m, n은 화학반응식 계수가 아니라 실험으로 정함":"반응 차수는 각 반응물 농도가 속도에 미치는 영향의 지수로, 반응식 계수와 달리 실험으로 결정해야 합니다.","반응 엔탈피 ΔH와 평형 상수, 평형 조성은 바꾸지 않고 평형에 빨리 도달하게 함":"촉매는 반응 경로만 바꾸므로 엔탈피 변화·평형 상수·평형 조성은 그대로이고 평형 도달 시간만 줄입니다.","반응이 일어나려면 활성화 에너지 이상의 에너지와 알맞은 방향을 가진 유효 충돌이 필요":"충돌만으로는 반응이 안 되고, 활성화 에너지 이상의 에너지와 알맞은 방향이 갖춰진 유효 충돌이어야 합니다.","반지름 R인 원형 평행판 축전기를 전류 i로 충전할 때, 판 사이 중심축에서 r(< R)인 곳의 자기장은 B = μ₀ir/(2πR²)로 r에 비례":"원형 축전기 안에서는 중심에서 떨어진 거리의 제곱에 비례하는 전류를 둘러싸므로 자기장이 그 거리에 비례합니다.","반지름 r = mv/(qB), 주기 T = 2πm/(qB)로 주기는 속력과 무관":"원운동 반지름은 속력에 비례하지만 주기는 속력이 소거되어, 입자 질량과 전하, 자기장 세기만으로 정해집니다.","발산 경계는 판이 멀어지는 곳으로 대서양 중앙 해령과 동아프리카 열곡대가 예":"대서양 중앙 해령과 동아프리카 열곡대는 판이 서로 멀어지며 새 지각이 만들어지는 발산 경계의 예입니다.","밤에 기공을 열어 CO₂를 유기산으로 고정":"CAM 식물은 낮의 수분 손실을 줄이려고 밤에 기공을 열어 CO₂를 유기산 형태로 고정해 둡니다.","방출 에너지는 질량결손 Δm에 대해 E = Δmc²":"핵반응에서 줄어든 질량인 질량결손이 에너지로 방출되며, 그 크기는 질량결손에 빛 속력의 제곱을 곱한 값입니다.","방해석(CaCO₃)과 돌로마이트(CaMg(CO₃)₂)는 탄산염, 암염(NaCl)은 할로젠화, 황동석(CuFeS₂)은 황화, 금강석은 원소 광물":"광물은 음이온 성분에 따라 분류하며, 방해석·돌로마이트는 탄산염, 암염은 할로젠화, 황동석은 황화 광물입니다.","방향은 오른손 법칙으로 정함":"전류가 만드는 자기장의 방향은 오른손을 이용한 규칙으로 정하며, 직선 도선에서는 엄지가 전류 방향입니다.","배위수 6인 착화합물은 팔면체 구조":"배위수가 6이면 리간드 여섯 개가 중심 금속 둘레에 정팔면체 모양으로 배치됩니다.","베게너는 대서양 양쪽 해안선의 일치, 같은 화석의 분포, 고생대 말 남반구 여러 대륙의 빙하 흔적, 북아메리카와 유럽 산맥의 지질 구조 연속을 증거로 들었음":"베게너가 든 대륙 이동의 증거는 해안선 모양, 화석 분포, 빙하 흔적, 산맥의 지질 구조가 대륙 사이에 이어진다는 점입니다.","벤젠은 첨가가 아니라 고리의 H를 바꾸는 친전자성 방향족 치환 반응을 함":"벤젠은 안정한 방향족 고리를 유지하려고 첨가 대신 고리의 수소를 다른 원자단이 대체하는 친전자성 치환을 합니다.","변하는 전기장 선속은 변위전류 I_d = ε₀dΦ_E/dt를 만들어 자기장을 유도":"변하는 전기장도 자기장을 만들 수 있다는 맥스웰의 보완으로, 전기선속의 시간 변화가 변위전류 역할을 합니다.","별의 광도는 L = 4πR²σT⁴":"별의 광도는 표면적과 표면 온도의 네제곱에 비례하는 슈테판-볼츠만 법칙으로 구합니다.","보존 경계(변환 단층)인 산안드레아스 단층에서는 천발지진이 일어남":"변환 단층은 판이 서로 어긋나 지나가는 보존 경계로, 산안드레아스 단층에서는 깊이가 얕은 지진이 일어납니다.","불연속 계열은 감람석 → 휘석 → 각섬석 → 흑운모 순으로, 연속 계열은 Ca 사장석에서 Na 사장석으로 정출":"보웬의 반응 계열에서 불연속 계열은 유색 광물이 차례로 정출하고, 연속 계열은 사장석의 성분이 Ca에서 Na로 바뀝니다.","불포화도 = (2C + 2 + N - H - X)/2이며 고리 하나나 이중결합 하나가 1":"불포화도는 수소가 부족한 정도를 뜻하며 고리나 이중결합 하나마다 1씩 늘고 삼중결합은 둘로 셉니다.","빙하 코어와 심해저 퇴적물, 나무 나이테로 과거 기후를 추정":"과거 기후는 빙하 코어, 심해저 퇴적물, 나무 나이테에 남은 기록을 분석해 추정합니다.","산성에서 2MnO₄⁻ + 5SO₃²⁻ + 6H⁺ → 2Mn²⁺ + 5SO₄²⁻ + 3H₂O":"산성 용액에서 과망간산 이온과 아황산 이온이 반응하는 균형 맞춘 알짜 이온 반응식입니다.","산소산 HXO의 산 세기는 중심 원자의 전기음성도가 클수록 커서 HClO > HBrO > HIO":"중심 원자의 전기음성도가 클수록 O-H 결합의 전자를 더 끌어당겨 H⁺가 잘 떨어지므로 산이 더 셉니다.","산화수 변화로 주고받는 전자 수를 맞춘 뒤 산성 용액에서는 H⁺와 H₂O로, 염기성 용액에서는 H⁺를 같은 수의 OH⁻로 바꿔 H₂O로 정리":"산화수 변화로 전자 수를 맞춘 뒤 용액 조건에 따라 H⁺, H₂O 또는 OH⁻로 원자와 전하를 맞추는 균형 잡기 절차입니다.","산화적 인산화는 미토콘드리아 내막의 전자전달계에서 일어남":"산화적 인산화는 미토콘드리아 내막에 있는 전자전달계에서 ATP를 대량 합성하는 단계입니다.","삼중결합은 σ 결합 1개와 π 결합 2개로 이루어짐":"삼중결합 하나는 축 방향의 시그마 결합 하나와 서로 수직인 두 파이 결합으로 구성됩니다.","상반 연관(Ad/aD) 개체를 자가교배하면 자손은 Ad/Ad 1/4, Ad/aD 1/2, aD/aD 1/4":"상반 연관이면 교차 없이 Ad 또는 aD 배우자만 만들어져, 자가교배 자손은 1/4, 1/2, 1/4 비로 나옵니다.","서던 블롯은 DNA, 노던 블롯은 RNA, 웨스턴 블롯·ELISA·에드만 분해·등전점 전기영동은 단백질을 분석":"서던 블롯은 DNA, 노던 블롯은 RNA를 검출하고, 웨스턴 블롯 등 나머지는 단백질을 분석하는 방법입니다.","선구동물 중 연체·환형·편형동물이 속함":"촉수담륜동물은 선구동물에 속하며 연체동물, 환형동물, 편형동물이 여기에 들어갑니다.","선구동물 중 절지·선형동물이 속함":"탈피동물은 선구동물이며 허물을 벗는 절지동물과 선형동물이 속합니다.","선도가닥은 연속 합성되고, 지연가닥은 불연속으로 합성되어 오카자키 절편이 생김":"복제 분기점에서 한쪽 가닥은 진행 방향과 합성 방향이 같아 연속되고, 반대쪽은 조각조각 합성돼 오카자키 절편이 생깁니다.","선모로 세포가 연결되어 플라스미드 등을 옮기는 것":"접합은 선모로 두 세균이 이어져 플라스미드 같은 DNA가 직접 이동하는 유전자 전달입니다.","성간 티끌에 가려진 원반 구조는 중성수소가 내는 21 cm 전파로 알아냄":"가시광선이 성간 티끌에 가려지므로 중성수소가 내는 21 cm 전파로 우리은하 원반 구조를 관측합니다.","성질이 다른 찬 기단과 따뜻한 기단이 만나는 곳에서 생김":"온대 저기압은 성질이 다른 찬 공기와 따뜻한 공기가 부딪치는 경계에서 발생합니다.","세균은 RNA 중합효소가 한 종류이고 히스톤이 없으며 세포벽에 펩티도글리칸이 있음":"세균은 RNA 중합효소가 한 종류뿐이고 핵산을 감는 히스톤이 없으며 세포벽 성분이 펩티도글리칸이라는 점이 특징입니다.","세포골격 굵기는 미세소관(약 25 nm) > 중간섬유(8~12 nm) > 미세섬유(약 7 nm)":"세포골격은 굵기 순서로 미세소관이 가장 굵고 중간섬유가 중간, 미세섬유가 가장 가는 순서입니다.","세포독성 T세포는 MHC I로 제시된 항원을 인식해 감염된 세포를 죽임":"세포독성 T세포는 MHC I에 올라온 항원을 인식하고 감염된 세포를 직접 죽입니다.","세포 밖 DNA를 직접 받아들이는 것":"형질전환은 세균이 주변 환경의 DNA를 직접 흡수해 자기 유전 정보로 받아들이는 유전자 전달입니다.","세포벽 성분은 세균 펩티도글리칸, 균류(효모·곰팡이) 키틴·글루칸, 식물 셀룰로오스":"세포벽의 주성분은 생물군마다 달라 세균은 펩티도글리칸, 균류는 키틴·글루칸, 식물은 셀룰로오스입니다.","세포 표면 수용체(G 단백질 연결 수용체 등)에 결합":"수용성 호르몬은 세포 표면 수용체에 결합해 세포 안으로 신호를 전달하며 G 단백질 연결 수용체가 한 예입니다.","세포호흡의 전자운반체는 NAD⁺와 FAD":"세포호흡에서 전자를 운반하는 물질은 NAD⁺와 FAD이며 환원되어 에너지를 전달합니다.","소리는 종파이고 빛은 횡파라서 빛만 편광됨":"편광은 횡파만 가능하므로 종파인 소리는 편광되지 않고 횡파인 빛만 편광됩니다.","속도 상수는 k = Ae^(-Ea/RT)":"아레니우스 식에서 속도 상수는 빈도 인자에 활성화 에너지와 온도로 정해지는 지수 항을 곱한 값입니다.","속씨식물은 꽃을 가진 종자식물로 식물계에서 가장 다양하고 널리 분포":"속씨식물은 꽃과 씨방 속 종자를 가진 식물군으로 식물계에서 종류가 가장 많고 널리 퍼져 있습니다.","수렴 경계 중 해양판이 대륙판 아래로 섭입하면 해구와 안데스 산맥 같은 습곡산맥이, 대륙판끼리 충돌하면 히말라야·알프스 산맥이 생김":"수렴 경계에서 섭입이 일어나면 해구와 안데스 같은 산맥이 생기고, 대륙판끼리 충돌하면 히말라야·알프스 같은 산맥이 생깁니다.","수소 질량 백분율 = 수소 질량÷분자량×100":"수소 질량 백분율은 분자 속 수소 원자들의 질량 합을 분자량으로 나눈 뒤 백을 곱한 값입니다.","수온과 염분에 따른 밀도 차로 일어나는 심층 순환을 열염순환이라 함":"열염순환은 수온과 염분으로 결정되는 밀도 차가 일으키는 해수의 심층 순환입니다.","스테로이드 호르몬 같은 지용성 호르몬은 세포막을 통과":"스테로이드 호르몬은 지용성이라 세포막을 직접 통과해 세포 안의 수용체와 결합할 수 있습니다.","신경세포 말단에서 시냅스 틈으로 확산":"신경전달물질은 신경세포 말단에서 방출되어 시냅스 틈을 확산해 건너가 바로 맞닿은 세포에 작용합니다.","아미노산이 펩티드 결합으로 이어진 서열이 1차 구조이고, 펩티드 결합은 물이 빠지는 탈수 축합으로 생김":"아미노산이 탈수 축합으로 펩티드 결합을 이룬 사슬의 서열이 1차 구조이며, 이 결합 때 물이 한 분자씩 빠집니다.","아밀로오스는 포도당이 α-1,4 글리코시드 결합으로 이어지고, 아밀로펙틴과 글리코겐은 가지 부분에 α-1,6 결합이 있음":"아밀로오스는 가지가 없고 아밀로펙틴과 글리코겐은 α-1,6 결합으로 가지를 칩니다.","아세틸렌에 산 촉매로 물을 첨가하면 엔올(비닐알코올)을 거쳐 호변이성질화로 아세트알데하이드 CH₃CHO가 됨":"물이 삼중결합에 첨가돼 생긴 엔올은 불안정해 호변이성질화로 카보닐 화합물인 아세트알데하이드가 됩니다.","아열대 환류는 북반구에서 시계 방향, 남반구에서 반시계 방향으로 돎":"아열대 환류는 북반구에서는 시계 방향, 남반구에서는 반시계 방향으로 도는 표층 해류의 큰 순환입니다.","알렌(H₂C=C=CH₂)의 가운데 탄소는 sp이고 양 끝 CH₂ 평면이 서로 수직이라 모든 원자가 한 평면에 있지 않음":"알렌의 가운데 탄소는 sp라 양 끝 CH₂의 평면이 서로 수직이 되어 모든 원자가 한 평면에 놓이지 못합니다.","알짜힘 F = ma이고 운동량 p = mv, 충격량 FΔt = Δp":"알짜힘은 질량과 가속도의 곱이고, 충격량은 힘에 작용 시간을 곱한 값으로 운동량의 변화량과 같습니다.","양 끝이 고정된 길이 L인 줄의 정상파는 λ = 2L/n(n = 1, 2, 3, …)":"양 끝이 고정된 줄에는 길이가 반파장의 정수배일 때만 정상파가 생겨 파장이 이산적인 값을 갖습니다.","양전하를 띤 히스톤과 음전하를 띤 DNA가 결합해 지름 약 11 nm의 뉴클레오솜을 만들고, 그 위 단계가 30 nm 섬유":"뉴클레오솜은 히스톤과 DNA가 정전기적으로 결합한 지름 약 11 nm의 단위이며 더 접히면 30 nm 섬유가 됩니다.","억제자에 의한 음성 조절(유도자 알로락토스가 붙은 억제자는 작동자에서 떨어짐)":"젖당 오페론의 음성 조절이란 억제자가 작동자에 붙어 전사를 막다가, 알로락토스가 억제자에 결합하면 떨어져 전사가 허용되는 방식입니다.","에틸렌 C₂H₄는 4/28 ≈ 14.3%, 아세틸렌 C₂H₂는 2/26 ≈ 7.7%, 알렌 C₃H₄는 4/40 = 10%":"세 분자 모두 분자식에서 수소 질량을 분자량으로 나눠 구하며, 그 결과 에틸렌이 가장 크고 아세틸렌이 가장 작습니다.","엑손과 인트론이 모두 전사되고 인트론은 스플라이싱으로 제거됨":"엑손과 인트론이 모두 전사되지만 인트론은 스플라이싱으로 잘려 나가 성숙 mRNA에는 엑손만 남습니다.","여러 단계로 이루어진 반응에서 가장 느린 단계가 속도 결정 단계이고 전체 속도 법칙은 이 단계로 정해짐":"여러 단계 반응에서는 가장 느린 단계가 전체 속도를 제한해, 이 단계의 반응물로 속도 법칙이 정해집니다.","역전사효소로 RNA에서 cDNA를 만들고 유전자 특이적 프라이머, 열안정성 DNA 중합효소, dNTP로 증폭":"RT-PCR는 역전사효소로 RNA를 cDNA로 바꾼 뒤 특이적 프라이머와 열에 강한 DNA 중합효소로 증폭하는 방법입니다.","열대우림은 연중 고온다습해 기온 변화가 작고, 단위 면적당 식물 종 다양성이 육상생태계 중 가장 높음":"열대우림은 기후가 한결같이 따뜻하고 습해 연중 기온 차가 작고, 육상생태계 가운데 식물 종이 가장 다양합니다.","열은 3차 구조를 풀어 변성시키며, 4차 구조 없이 폴리펩티드 하나로 기능하는 단백질도 많음":"열은 3차 구조를 풀어 단백질을 변성시키고, 폴리펩티드 하나만으로 완성되어 4차 구조가 없는 단백질도 많습니다.","염기 중 아데닌·구아닌은 퓨린, 시토신·티민·우라실은 피리미딘이며 뉴클레오티드는 포스포디에스터 결합으로 이어짐":"염기는 구조에 따라 퓨린과 피리미딘으로 나뉘고, 뉴클레오티드끼리는 포스포디에스터 결합으로 사슬을 이룹니다.","영의 이중슬릿에서 밝은 무늬 간격은 Δx = Lλ/d(L 스크린 거리, d 슬릿 간격)":"영의 이중슬릿에서는 밝은 무늬 간격이 파장과 스크린 거리에 비례하고 슬릿 간격에 반비례합니다.","오리온자리 말머리성운은 우리은하 안의 암흑성운":"말머리성운은 오리온자리에 있는, 뒤쪽 빛을 가리는 우리은하 안의 암흑성운입니다.","오존의 자외선 흡수로 위로 갈수록 기온이 올라 상부 경계(약 50 km)에서 가장 높음":"성층권은 오존이 자외선을 흡수해 위로 갈수록 기온이 올라가 상부 경계에서 가장 높습니다.","온도가 높을수록, 활성화 에너지 Ea가 작을수록 k가 커짐":"온도가 높아 충돌 에너지가 커지거나 활성화 에너지가 작아 장벽이 낮을수록 속도 상수가 커집니다.","온도 변화에 필요한 열량은 Q = mcΔT(c는 비열)":"비열이 클수록 같은 질량의 온도를 바꾸는 데 열이 더 들며, 열량은 질량·비열·온도 변화의 곱입니다.","옴의 법칙은 V = IR이고 전력은 P = VI = I²R = V²/R":"옴의 법칙은 전압이 전류와 저항의 곱이라는 것이고, 전력은 전압과 전류의 곱이며 저항을 써서도 나타냅니다.","외력이 없으면 충돌 전후 운동량의 합이 보존":"외력이 없는 계에서는 충돌 전 총 운동량과 충돌 후 총 운동량이 같다는 법칙입니다.","외핵은 액체라 S파가 통과하지 못하므로 S파 암영대는 진앙각 103° 이상 전체이고, P파 암영대(103°~142°)는 그보다 좁음":"외핵은 액체여서 S파를 통과시키지 않아 S파 암영대가 넓고, P파는 굴절되어 암영대가 그보다 좁습니다.","용수철의 탄성 위치에너지는 ½kx²":"용수철을 늘이거나 줄인 길이의 제곱에 비례해 저장되는 탄성 위치에너지입니다.","용수철 진자의 주기는 T = 2π√(m/k)이고, 진폭이 작은 단진자의 주기는 T = 2π√(L/g)로 질량과 무관":"용수철 진자의 주기는 질량과 용수철 상수로, 단진자의 주기는 길이와 중력가속도로 정해지며 단진자는 질량과 무관합니다.","용암류로 조용히 분출해 경사가 완만한 화산체를 만듦":"점성이 낮은 마그마는 가스가 쉽게 빠져 용암이 조용히 흘러나오며 완만한 경사의 화산체가 만들어집니다.","용액을 냉각해 부피가 줄면 몰농도는 커지지만 질량 백분율은 그대로":"냉각으로 부피만 줄면 용질 양은 그대로라 몰농도는 커지지만, 질량 비율은 변하지 않아 질량 백분율은 같습니다.","용융은 정출의 역순으로 일어나며 사장석은 Ca-Na 고용체":"용융은 정출 순서의 반대로 일어나고, 사장석은 Ca와 Na가 섞여 이루는 고용체입니다.","우리은하는 막대 나선은하이고 태양은 원반의 나선팔(오리온 팔 부근)에 있음":"우리은하는 막대 나선은하이며 태양은 중심이 아닌 원반의 나선팔인 오리온 팔 부근에 위치합니다.","우리은하의 회전 속도는 중심에서 수백 pc까지 급히 커진 뒤 바깥쪽에서 거의 일정하게 유지되며, 이는 보이지 않는 암흑물질이 있다는 근거":"우리은하 회전 속도가 바깥에서도 일정하게 유지되는 것은 눈에 보이지 않는 암흑물질이 있다는 증거입니다.","원구가 항문이 되며 입은 반대쪽에 새로 생김":"후구동물은 발생 초기의 원구가 항문이 되고 입은 반대쪽에 새로 만들어지는 동물군입니다.","원핵생물은 오페론으로 한 프로모터에서 여러 유전자를 하나의 mRNA로 전사":"원핵생물은 오페론이라는 한 묶음의 유전자들이 한 프로모터 아래 하나의 mRNA로 함께 전사됩니다.","위로 갈수록 기온이 내려가고 기상 현상이 나타나며 두께는 적도(약 16~18 km)가 극(약 8~10 km)보다 두꺼움":"대류권은 위로 갈수록 기온이 내려가고 기상 현상이 일어나며, 두께는 적도 쪽이 극보다 두껍습니다.","위로 갈수록 기온이 내려가 대류가 일어나지만 수증기가 거의 없어 기상 현상은 없음":"중간권은 위로 갈수록 기온이 내려가 대류는 있으나 수증기가 거의 없어 날씨 변화가 나타나지 않습니다.","유기물이 빨리 분해되고 양분이 씻겨 나가 토양은 산성이고 척박":"높은 온도와 습도 탓에 유기물이 빨리 분해되고 양분이 비에 씻겨 나가므로 토양은 산성이고 영양분이 적습니다.","유도기전력은 ε = -dΦ/dt(패러데이 법칙)":"패러데이 법칙은 유도기전력이 자기선속의 시간 변화율에 비례하며 음의 부호가 붙는다는 것입니다.","유도전류는 자속 변화를 방해하는 방향으로 흐름(렌츠 법칙)":"렌츠 법칙은 유도전류가 원래 자속의 변화를 막는 쪽으로 흐른다는 법칙입니다.","유전암호는 중복되어 있어 코돈이 바뀌어도 아미노산이 그대로인 침묵 돌연변이가 있음":"한 아미노산을 여러 코돈이 지정하는 중복성 때문에 염기가 바뀌어도 아미노산이 그대로인 침묵 돌연변이가 생깁니다.","유전자 부동은 우연에 의해 대립유전자 빈도가 세대마다 무작위로 변하는 현상이며 작은 집단에서 큼":"유전자 부동은 우연으로 대립유전자 빈도가 세대마다 무작위로 바뀌는 현상이며 집단이 작을수록 효과가 큽니다.","유전자 흐름은 개체나 배우자의 이동으로 빈도를 바꾸고, 균형선택에는 빈도 의존적 선택과 이형접합자 우위(잡종강세)가 있음":"개체나 배우자가 이동하면 집단 사이에 대립유전자가 섞여 빈도가 바뀌고, 균형선택은 변이를 유지하는 방향으로 작용합니다.","은하 중심 방향은 궁수자리 쪽":"우리은하 중심은 지구에서 볼 때 궁수자리 방향에 있습니다.","음원과 관측자가 가까워지면 관측 진동수가 커지고 멀어지면 작아짐":"도플러 효과는 서로 가까워지면 파면이 촘촘히 도달해 진동수가 커지고, 멀어지면 성기게 도달해 작아지는 현상입니다.","이들은 개체 사이의 수평적 유전자 전이이며 항생제는 내성균을 선택해 그 비율을 늘림":"세 방식 모두 한 세대 안에서 서로 다른 개체 사이로 유전자가 옮겨지는 수평적 전이이며, 항생제는 내성균의 비율을 높이는 선택압이 됩니다.","이런 염색질 변형은 되돌릴 수 있음":"이런 후성유전적 변형은 효소로 되돌릴 수 있어서 DNA 염기서열은 바뀌지 않은 채 유전자 발현만 가역적으로 달라집니다.","이상기체는 PV = nRT를 따르며 T는 절대온도(K)":"이상기체의 압력·부피·온도·몰수 관계식이며, 온도는 켈빈 단위의 절대온도를 써야 합니다.","이온의 결합 차수는 전자를 더하거나 빼서 같은 방식으로 셈":"이온이 되면 전자를 더하거나 빼서 채워진 궤도를 바꾸고 같은 식으로 결합 차수를 다시 계산합니다.","일 W = Fs cosθ이고 알짜힘이 한 일은 운동에너지 변화량과 같음":"힘과 변위 사이 각이 일의 크기를 정하며, 일-에너지 정리에 따라 알짜힘이 한 일이 곧 운동에너지의 변화입니다.","일률 P = W/t = Fv":"일률은 단위 시간당 한 일이며, 힘이 일정하고 속도가 있으면 힘과 속도의 곱으로도 구합니다.","자기력은 속도에 수직이라 일을 하지 않아 운동에너지 ½mv²가 일정":"자기력은 속도와 수직이라 일을 하지 못하므로 속력과 운동에너지가 변하지 않습니다.","전기용량 C = Q/V이고 평행판 축전기는 C = ε₀A/d":"전기용량은 저장된 전하를 전압으로 나눈 값이며, 평행판에서는 면적에 비례하고 판 간격에 반비례합니다.","전리층이 있고 오로라가 나타남":"열권에는 전리층이 있어 전파가 반사되고, 오로라가 나타나는 대기층입니다.","전자는 L = 1 nm일 때 E₁ ≈ 0.376 eV":"폭이 1 nm인 우물의 전자는 바닥 에너지가 약 0.376 eV라는 계산 결과입니다.","전체 차수는 m + n이고 속도 상수 k는 온도에 따라 달라짐":"전체 반응 차수는 각 반응물 차수의 합이고, 속도 상수는 온도가 바뀌면 값이 달라집니다.","정사면체 결정장에서 d 오비탈은 e(dz², dx²-y²)가 아래, t₂(dxy, dxz, dyz)가 위로 갈라짐":"정사면체 결정장에서는 팔면체와 반대로 e 궤도가 낮고 t₂ 궤도가 높아 d 오비탈이 갈라집니다.","줄을 따라 가는 파동의 속력은 v = √(F/μ)(F 장력, μ 선밀도)":"줄 파동의 속력은 장력이 클수록 빠르고 선밀도가 클수록 느리며 각각 제곱근에 비례·반비례합니다.","중복수정은 속씨식물에만 있으며 외떡잎식물과 쌍떡잎식물이 모두 속씨식물":"중복수정은 속씨식물에서만 나타나며, 외떡잎식물과 쌍떡잎식물은 둘 다 속씨식물에 속합니다.","지진해일은 파장이 수심보다 훨씬 길어 깊은 바다에서도 천해파(장파)로 행동하며 속력은 v = √(gh)로 수심에만 관계됨":"지진해일은 파장이 수심보다 훨씬 길어 깊은 바다에서도 장파로 행동하므로 속력이 중력가속도와 수심의 곱의 제곱근입니다.","직렬연결 합성저항은 R₁ + R₂, 병렬연결은 1/R = 1/R₁ + 1/R₂":"직렬이면 저항을 더하고 병렬이면 역수끼리 더해, 병렬 합성저항은 가장 작은 저항보다도 작습니다.","진동수는 f = nv/(2L)":"진동수는 파동 속력을 파장으로 나눈 값이므로, 허용되는 정상파 진동수는 정수 n에 비례하는 이산 값입니다.","진핵세포에서 전사와 mRNA 가공(5' 캡, 폴리 A 꼬리, 스플라이싱)은 핵에서, 번역은 세포질의 리보솜에서 tRNA를 이용해 일어남":"진핵세포는 핵에서 전사와 mRNA 가공을 마친 뒤 세포질 리보솜에서 tRNA의 도움으로 번역해 장소가 나뉩니다.","질량과 자기장 세기가 가장 큰 것은 목성, 평균 밀도가 가장 작은 것은 토성(약 0.69 g/cm³로 물보다 작음)":"목성은 질량과 자기장이 가장 크고 토성은 평균 밀도가 약 0.69 g/cm³로 물보다 작아 가장 작습니다.","차원 분석으로 v = CFˣμʸ에서 x = ½, y = -½을 얻으며 장력을 2배로 하면 속력은 √2배":"양변의 차원이 맞아야 하므로 장력은 제곱근 지수로, 선밀도는 음의 제곱근 지수로 정해지고 장력을 두 배로 하면 속력이 제곱근 두 배가 됩니다.","착이온이 생기면 A⁺가 소모되어 난용성 염의 용해도가 커짐":"착이온이 만들어지며 용액 속 A⁺가 줄면 르샤틀리에 원리로 용해가 더 진행되어 난용성 염의 용해도가 커집니다.","창시자 효과와 병목 효과는 유전자 부동의 예":"창시자 효과와 병목 효과는 소수 개체에서 집단이 이어지며 빈도가 우연히 바뀌는 유전자 부동의 대표 사례입니다.","처음부터 B가 있으면 생성된 양 x를 더해 P_B = P_B,0 + x, P_C = x로 놓고 전체 압력 조건으로 x를 구함":"처음 B의 압력이 있으면 반응으로 늘어난 양만큼 더해 B와 C의 분압을 놓고 전체 압력 조건으로 미지수를 구합니다.","처음 속력 v₀에서 등가속도로 멈출 때 평균 속력은 v₀/2이므로 이동 거리는 s = v₀t/2":"가속도가 일정하면 속력이 고르게 줄어 평균 속력이 처음 속력의 절반이 되므로, 거리는 평균 속력에 시간을 곱한 값입니다.","천왕성과 해왕성은 대기의 메탄이 붉은빛을 흡수해 푸르게 보임":"천왕성과 해왕성이 푸르게 보이는 것은 대기의 메탄이 붉은빛을 흡수하기 때문입니다.","촉매는 활성화 에너지가 낮은 다른 경로를 제공해 정반응과 역반응을 모두 빠르게 함":"촉매는 활성화 에너지가 낮은 새 반응 경로를 열어 정반응과 역반응 속도를 함께 빠르게 합니다.","총단면적은 모세혈관이 가장 크고, 그래서 혈류 속도는 모세혈관에서 가장 느림":"모세혈관은 총단면적이 가장 커서 같은 혈액량이 퍼지므로 혈류 속도가 가장 느립니다.","캘빈 회로는 스트로마에서 루비스코가 CO₂를 RuBP에 고정하며 직접 만드는 탄수화물은 G3P(PGAL)":"캘빈 회로는 스트로마에서 일어나 루비스코가 이산화탄소를 RuBP에 붙이고, 직접 만드는 당은 G3P입니다.","탄성에너지가 처음 방출된 지점이 진원이고 그 바로 위 지표가 진앙":"진원은 지진이 처음 일어난 지하 지점이고 진앙은 그 바로 위의 지표 지점입니다.","탄성 충돌에서는 운동에너지도 보존":"탄성 충돌은 에너지 손실이 없는 충돌이라 운동량과 운동에너지가 모두 충돌 전후에 같습니다.","태양-달-지구 순으로 늘어선 삭일 때 일어남":"일식은 태양과 지구 사이에 달이 놓이는 삭에 달이 태양을 가리며 일어납니다.","태양-지구-달 순으로 늘어선 망일 때 일어남":"월식은 달이 지구 그림자 속에 들어가는 현상으로 지구가 태양과 달 사이에 놓이는 망일 때 일어납니다.","태양은 고온으로 이온화된 플라스마 상태":"태양은 고온으로 원자가 이온화돼 양이온과 전자가 섞인 플라스마 상태의 천체입니다.","태양 활동과 지구 공전궤도 변화는 기후변화의 외적 요인, 대기·해양 상호작용과 화산 활동, 지표 변화는 내적 요인":"기후변화 요인은 지구 밖에서 오는 외적 요인과 지구 시스템 안에서 생기는 내적 요인으로 나뉩니다.","파동 속력은 v = ω/k = fλ":"파동 속력은 각진동수를 파수로 나눈 값이며 진동수와 파장의 곱과 같습니다.","파장 500 nm 광자는 약 2.48 eV":"광자 에너지 근사식에 파장 500 nm를 넣으면 약 2.48 eV가 나온다는 계산 예입니다.","판 바깥(r > R)에서는 B = μ₀i/(2πr)":"판 바깥에서는 변위전류 전체를 둘러싸므로 자기장이 긴 직선 도선처럼 거리에 반비례합니다.","펩타이드 호르몬과 에피네프린 같은 수용성 호르몬은 세포막을 통과하지 못함":"수용성 호르몬은 지질 이중층을 통과하지 못해 세포 안으로 들어가지 못하고 막의 수용체에 신호를 전합니다.","평형 상수 식에는 기체와 수용액 화학종만 넣고 고체와 순수한 액체는 넣지 않음":"평형 상수 식에는 농도가 변하는 기체와 수용액 화학종만 넣고, 농도가 일정한 고체와 순수한 액체는 제외합니다.","평형 조건은 돌연변이 없음, 무작위 교배, 유전자 흐름(이입·이출) 없음, 매우 큰 집단, 자연선택 없음":"하디-바인베르크 평형은 돌연변이, 선택, 유전자 흐름이 없고 집단이 크며 교배가 무작위일 때 유지되는 조건입니다.","평형 집단에서 대립유전자 빈도 p, q에 대해 유전자형 빈도는 p² + 2pq + q² = 1":"평형 집단에서는 대립유전자 빈도로 유전자형 빈도를 예측할 수 있고 세 유전자형 빈도의 합이 1입니다.","폭 L인 무한 퍼텐셜 우물에 갇힌 입자의 에너지는 Eₙ = n²h²/(8mL²)로 n²에 비례":"무한 퍼텐셜 우물에서 입자 에너지는 양자수 제곱에 비례하고 우물 폭 제곱에 반비례해 이산적으로 정해집니다.","폭발적으로 분출해 화산 쇄설물 비율이 높고 경사가 급한 화산체를 만듦":"점성이 높으면 가스가 빠지지 못해 폭발적으로 분출하며, 화산 쇄설물이 많아 경사가 급한 화산체가 만들어집니다.","폭풍해일에서 기압이 1 hPa 낮아지면 해수면이 약 1 cm 올라감":"폭풍해일에서는 기압이 낮아진 만큼 해수면이 들려 올라가며, 기압이 1 hPa 내려가면 해수면이 약 1 cm 상승합니다.","표면은 광구이고 그 바깥에 채층과 코로나가 있음":"태양 표면을 광구라 하고 그 바깥의 대기층이 채층과 코로나입니다.","표준화석은 생존 기간이 짧고 분포 면적이 넓으며 개체수가 많아 지층의 시대를 정하고, 시상화석은 생물이 살던 환경을 알려 줌":"표준화석은 짧은 기간 넓게 살아 시대를 알려 주고, 시상화석은 생물이 살던 당시의 환경을 알려 줍니다.","표층 해류는 바람과 해수면의 마찰로 생김":"표층 해류는 바람이 해수면과 마찰하며 해수를 끌고 가 생깁니다.","프리메이스가 RNA 프라이머를 만들고 DNA 중합효소가 5'→3' 방향으로 합성":"DNA 중합효소는 스스로 합성을 시작하지 못해, 프리메이스가 만든 프라이머에 5'→3' 방향으로만 뉴클레오티드를 이어 붙입니다.","한 사이클에 4000 J을 받아 1000 J의 일을 하면 효율은 0.25이고 3000 J을 저온부로 버림":"받은 열 대비 일의 비가 효율이며, 받은 열에서 일을 뺀 나머지가 저온부로 버려집니다.","할로젠 단체의 반응성은 F₂ > Cl₂ > Br₂ > I₂이고, Br₂는 25℃에서 적갈색 액체":"할로젠 단체의 반응성은 플루오린이 가장 크고 아이오딘이 가장 작으며, 브로민은 25℃에서 적갈색 액체입니다.","할로젠화 수소의 끓는점은 수소 결합 때문에 HF가 가장 높고 HCl이 가장 낮음":"HF만 분자 사이 수소 결합이 있어 끓는점이 비정상적으로 높고, 나머지는 분자량이 클수록 끓는점이 높아 HCl이 가장 낮습니다.","해당과정은 세포질에서 산소 없이 일어나 포도당 1분자를 피루브산 2분자로 나누며 ATP 2개를 쓰고 4개를 만들어 순 2개를 얻음":"해당과정은 세포질에서 산소 없이 진행되고, ATP를 두 개 쓰고 네 개를 만들어 순이득이 두 개입니다.","해안에 가까워져 수심이 얕아지면 속력이 줄고 파고가 높아짐":"수심이 얕아지면 속력이 줄면서 파의 에너지가 좁은 구간에 모여 파고가 높아집니다.","해양지각(현무암질, SiO₂ 약 50%)은 대륙지각(화강암질, SiO₂ 약 60~70%)보다 SiO₂가 적고 밀도가 큼":"해양지각은 대륙지각보다 SiO₂ 함량이 적은 현무암질이며 밀도는 더 큽니다.","핵반응에서 질량수의 합과 원자번호(전하)의 합은 보존":"핵반응에서는 질량수의 총합과 전하(원자번호)의 총합이 반응 전후에 변하지 않습니다.","혈압은 동맥에서 가장 높고 모세혈관, 정맥으로 갈수록 낮아짐":"혈압은 심장에서 멀어질수록 낮아져 동맥에서 가장 높고 모세혈관과 정맥으로 갈수록 떨어집니다.","호르몬이 혈액을 따라 먼 표적세포에 감":"내분비 신호는 분비된 호르몬이 혈액을 타고 멀리 떨어진 표적세포까지 이동해 작용하는 방식입니다.","환원되는 물질이 산화제이며, 수소 전극에서 H⁺는 전자를 받아 H₂가 되므로 산화제":"환원되는 물질이 산화제이므로 수소 전극에서 전자를 받아 수소 기체가 되는 H⁺가 산화제입니다.","활면소포체는 Ca²⁺를 저장하고, 글리옥시좀은 지방을 저장하는 식물 종자에 있음":"활면소포체는 칼슘 이온의 저장 장소이고, 글리옥시좀은 지방을 저장하는 식물 종자에서 발견됩니다.","활성부위를 두고 기질과 경쟁":"경쟁적 저해제는 기질과 모양이 비슷해 활성부위를 두고 다투므로 기질 농도를 높이면 저해가 줄어듭니다.","회전 운동에너지는 ½Iω²이고 미끄러짐 없이 구르면 v = ωR":"회전 운동에너지는 관성모멘트와 각속도로 정해지고, 미끄러짐 없이 구르면 중심 속력이 각속도와 반지름의 곱입니다.","히스톤 N-말단 꼬리의 아세틸화는 염색질을 느슨하게 해 전사를 촉진하고, DNA 메틸화는 전사를 억제":"히스톤 꼬리가 아세틸화되면 염색질이 느슨해져 전사가 잘 되고, DNA 메틸화는 전사를 억제하는 후성유전 변화입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
